# ── Temporal ──────────────────────────────────────────────────────────────

def as_of(result: dict, *,
          example: str | None = None,
          query: str = "`coderadar_query`",
          search: str = "`coderadar_search`") -> str:
    timestamp = result["timestamp"]
    if example is None:
        example = f'coderadar_as_of(timestamp="{timestamp}", symbols=["User"])'
    if not result["names"]:
        # Nothing is loaded at this point; as_of resolves per symbol.
        return "\n".join([
            f"## Snapshot at `{timestamp}`",
            "",
            (
                "Pass `symbols` to look entities up as they were at this "
                f"timestamp — for example {example}."
            ),
            "",
            (
                "Only symbol lookup is reconstructed from the ledger. "
                f"{query} and {search} always run against the "
                "current index."
            ),
        ])
    lines = [f"## Snapshot at `{timestamp}`", ""]
    # P5b.3a (§3.1.1): a caller must be able to tell an observation from a
    # reconstruction, so the CLI names the arm the read took.
    basis = result.get("basis")
    if basis == "git-history":
        commit = (result.get("commit") or "")[:12]
        lines += [
            (
                f"*From git history:* commit `{commit}`, the last one at or "
                f"before this instant — it predates the store's horizon "
                f"`{result.get('horizon')}`, which is where recorded "
                f"observation begins."
            ),
            "",
        ]
    elif basis == "valid":
        lines += [
            (
                "*From the valid axis:* the ledger's own intervals, so this "
                "is what was true in the repository at this instant - no "
                "horizon and no commit index are involved."
            ),
            "",
        ]
    elif basis == "recorded" and result.get("horizon"):
        lines += [
            (
                f"*From the recorded ledger:* this instant is at or after the "
                f"store's horizon `{result.get('horizon')}`, so the fold "
                f"answers what was recorded by then."
            ),
            "",
        ]
    for name in result["names"]:
        entity = result["entities"].get(name)
        if entity:
            lines.append(f"**{entity.get('name', name)}** ({entity.get('kind', '?')})")
            lines.append(f"- File: `{entity.get('file_path', '?')}`")
            sig = entity.get("signature")
            if sig:
                lines.append(f"- Signature: `{sig}`")
        else:
            lines.append(f"`{name}` — not found at {timestamp}")
        lines.append("")
    return "\n".join(lines)


def ingest_status(result: dict) -> str:
    """The store's own ingest state, one line per name (P9, Q-10).

    Counts before addresses: a reader looking for "is this store whole?"
    reads ``commits/completions`` and stops. An address-only name is
    marked as such (it has a tip and no history of its own), and every
    short lineage names the repair rather than leaving the count to speak
    for itself.
    """
    fmt = result.get("format")
    out = [
        "## Ingest state",
        "",
        f"format           {'commit-time (P5b.1+)' if fmt else 'analyze-only'}",
        "",
    ]
    rows = result.get("lineages") or []
    if not rows:
        out.append("No lineage is recorded: ingest a branch's history first.")
        return chr(10).join(out)
    for row in rows:
        commits = row.get("commits", 0)
        completions = row.get("completions", 0)
        head = (
            f"{row.get('name', '?')}"
            f"  gen {row.get('generation', 1)}"
            f"  commits {commits}/{completions}"
        )
        if row.get("address_only"):
            head += f"  address -> {(row.get('tip') or '?')[:12]}"
        else:
            if row.get("cursor"):
                head += f"  cursor {(row['cursor'])[:12]}"
            if row.get("horizon"):
                head += f"  horizon {row['horizon']}"
        if row.get("lineage") and row["lineage"] != row.get("name"):
            head += f"  (lineage {row['lineage']})"
        out.append(head)
        if not row.get("address_only") and completions < commits:
            out.append(
                f"  incomplete: {commits - completions} commit(s) lack a "
                f"completion mark - run backfill_commit_index for "
                f"{row.get('lineage', row.get('name'))}")
    return chr(10).join(out)


def verify_history(result: dict, *, offenders: int = 10) -> str:
    """Per-generation byte coverage as legible text (P1, DR-36).

    The table shape is the prototype's (`scripts/verify_history.py`): one
    row per generation, file-generation totals, coverage, and the capped
    offender sample beside its exact distinct count.
    """
    def coverage(counts: dict) -> float:
        total = sum(counts.values())
        return (counts.get("ok", 0) / total * 100.0) if total else 0.0

    out = [
        f"store            {result['store']}  (branch {result['branch']})",
        f"window           {result['window'][0]} .. {result['window'][1]}",
        (
            f"generations      {result['sampled']} sampled of "
            f"{result['total_generations']}"
        ),
        "",
        (
            f"{'generation':28} {'files':>6} {'ok':>6} {'no_digest':>10} "
            f"{'unresolv':>9} {'mismatch':>9} {'cov%':>7}"
        ),
    ]
    for gen in result["generations"]:
        c = gen["counts"]
        out.append(
            f"{gen['timestamp'][:28]:28} {gen['modules']:>6} {c.get('ok', 0):>6} "
            f"{c.get('no_digest', 0):>10} {c.get('unresolvable', 0):>9} "
            f"{c.get('digest_mismatch', 0):>9} {coverage(c):>6.1f}%"
        )
    t = result["totals"]
    out += [
        "",
        (
            f"totals (file-generations)  ok={t.get('ok', 0)}  "
            f"no_digest={t.get('no_digest', 0)}  "
            f"unresolvable={t.get('unresolvable', 0)}  "
            f"mismatch={t.get('digest_mismatch', 0)}  "
            f"malformed={t.get('digest_malformed', 0)}"
        ),
        f"byte coverage              {result['byte_coverage_pct']:.1f}%",
        f"distinct digests checked   {result['distinct_digests']}",
    ]
    if offenders:
        for outcome, paths in sorted(result["offender_sample"].items()):
            total = result["offender_distinct"][outcome]
            shown = paths[:offenders]
            out.append(f"\n{outcome} ({total} distinct files):")
            out += [f"  {p}" for p in shown]
            if total > len(shown):
                out.append(f"  ... and {total - len(shown)} more")
    return "\n".join(out)


def history_of(result: dict) -> str:
    """A file's content chain as legible text (P3, DR-38).

    One row per content version, newest first: short digest, interval,
    parent link, payload size. The open head is marked; a closed head
    means the file was deleted (retire cascade) or... nothing else
    closes it — only new content does.
    """
    versions = result["versions"]
    out = [
        f"file             {result['file']}",
        f"versions         {result['count']}",
        "",
        f"{'digest':10} {'valid_from':28} {'valid_to':28} {'parent':10} {'bytes':>8}",
    ]
    for v in versions:
        mark = " (open)" if v["open"] else ""
        parent = (v["parent_digest"] or "-")[:8]
        out.append(
            f"{v['digest'][:8]:10} {v['valid_from'][:28]:28} "
            f"{v['valid_to'][:28]:28} {parent:10} {v['size_bytes']:>8}{mark}"
        )
    return "\n".join(out)


def export_annotations(result: dict) -> str:
    """Annotation export report as legible text (P8, A-9).

    The document itself is the JSON (or the file); text shows what it
    carried and where it went.
    """
    out = [
        f"format           {result['format']}",
        f"rows             {result['rows']}",
        f"versions         {result['versions']}",
        f"path             {result.get('path') or '(stdout)'}",
    ]
    kinds = result.get("kinds") or {}
    if kinds:
        out.append(
            "kinds            " + "  ".join(f"{k}={v}" for k, v in kinds.items()))
    return "\n".join(out)


def import_annotations(result: dict) -> str:
    """Annotation import report as legible text (P8, A-9)."""
    out = [
        f"rows             {result['rows']}",
        f"versions         {result['versions']}",
        f"imported         {result['imported']}",
        f"verified         {result['verified']}",
    ]
    if result.get("store"):
        out.append(f"store            {result['store']}")
    skipped = result.get("skipped") or []
    out.append(f"skipped          {len(skipped)}")
    for id in skipped:
        out.append(f"  {id}")
    return "\n".join(out)


def rebuild(result: dict) -> str:
    """Store rebuild report as legible text (P8, A-9/INV-18).

    The three facts a rebuild must state: where the old store went, what
    the export carried, and whether every row verified on the way back in.
    """
    out = [
        f"rebuilt          {result['repo']}",
        f"store            {result['store']}",
        f"backup           {result.get('backup') or '(no store to keep)'}",
        (
            f"commits          ingested={result['commits_ingested']}  "
            f"skipped={result['commits_skipped']}  "
            f"failed_files={result['files_failed']}  "
            f"elapsed={result['elapsed_secs']}s"
        ),
        f"branches         {', '.join(result['branches'])}",
    ]
    export = result.get("export")
    if export:
        out.append(
            f"export           {export['rows']} row(s) / "
            f"{export['versions']} version(s) -> {export['path']}")
    imported = result.get("imported")
    if imported:
        out.append(
            f"imported         {imported['imported']} row(s), "
            f"verified {imported['verified']}, "
            f"skipped {len(imported.get('skipped') or [])}")
    embeddings = result.get("embeddings") or {}
    if not embeddings.get("embedded"):
        out.append("embeddings       skipped (run compute-embeddings to restore vectors)")
    return "\n".join(out)


def open_items(result: dict) -> str:
    """Open task items as a legible list (P6b).

    One row per item: where it sits (`about:line`), what it asks, and the
    id a revise names. Grouped by `about` so a file's items read together;
    the count is stated once, up top.
    """
    items = result["items"]
    scope = result.get("scope") or "(whole store)"
    if not items:
        return f"No open items under {scope}."
    lines = [f"## Open items: {scope}", f"{len(items)} item(s)", ""]
    current = None
    for item in items:
        if item["about"] != current:
            current = item["about"]
            lines.append(f"### `{current}`")
        lines.append(
            f"- line {item['line']}: {item['text']}  "
            f"(`{item['id']}`)")
    return "\n".join(lines)


def annotation_versions(result: dict) -> str:
    """Annotation/comment versions as legible text (P6a, DR-44).

    One row per version, newest first: id, open count, interval, and
    whether the version is the live head or retired. Shared by the four
    read surfaces (the body itself is in the JSON — text shows the
    chain, not the prose).
    """
    versions = result["versions"]
    subject = result.get("target", result.get("id", "?"))
    out = [
        f"subject          {subject}",
        f"versions         {result['count']}",
        "",
        f"{'id':34} {'open':>4} {'valid_from':28} {'valid_to':28} {'state'}",
    ]
    for v in versions:
        if v["current"]:
            state = "current"
        elif v["retired"]:
            state = "retired"
        else:
            state = "superseded"
        out.append(
            f"{v['id']:34} {v['open']:>4} {v['valid_from'][:28]:28} "
            f"{v['valid_to'][:28]:28} {state}"
        )
    return "\n".join(out)


def annotation_stored(result: dict) -> str:
    """An annotation/comment write as legible text (P6a, DR-44).

    Shared by annotate/comment (minted) and revise (superseded) / retire
    (closed): the id, what happened, and whether the linter repaired
    the input on the way in.
    """
    if "repaired" in result and "about" in result:
        action = "minted"
    elif result.get("revised"):
        action = "revised"
    elif "revised" in result:
        action = "unchanged"
    else:
        action = "retired" if result.get("retired") else "already retired"
    lines = [f"{action:16} {result['id']}"]
    if "open" in result:
        lines.append(f"open             {result['open']}")
    if result.get("repaired"):
        lines.append("repaired         input repaired by the linter (stored canonically)")
    return "\n".join(lines)


def ingest_history(result: dict) -> str:
    """Commit-driven ingest report as legible text (P5a.3, DR-41).

    Counts first, then the two auditable lists: skipped commits with
    reasons, failed files with reasons. The JSON report is complete;
    this render shows every skip and failure uncapped (they are the
    signal, not the noise).
    """
    head = [
        f"branch           {result['branch']}  (lineage {result['lineage']})",
        f"from             {result['from'] or '(root)'}",
        f"fork             {result.get('fork_point') or '(trunk)'}",
        f"head             {result['head'] or '(unchanged)'}",
        f"belief           {result.get('belief_start') or '(none)'}",
        (
            f"commits          ingested={result['commits_ingested']}  "
            f"skipped={len(result['commits_skipped'])}  "
            f"ghosts={result['ghost_commits']}"
            f"{'  DRY RUN' if result['dry_run'] else ''}"
        ),
        (
            f"files            parsed={result['files_parsed']}  "
            f"failed={len(result['files_failed'])}  "
            f"excluded={result['files_excluded']}"
        ),
        (
            f"blobs            stored={result['blobs_stored']}  "
            f"deduped={result['blobs_deduped']}  "
            f"stamps_nudged={result['stamps_nudged']}"
        ),
        f"elapsed          {result['elapsed_secs']:.1f}s",
    ]
    out = head
    window = result.get("window")
    if window:
        out.append("")
        out.append(
            f"backfill window  ({window['from'] or '(root)'}, {window['to']})  "
            f"commits={window['commits']}  edges_skipped={window['edges_skipped']}"
        )
    if result["commits_skipped"]:
        out.append("\nskipped commits:")
        out += [f"  {s['sha'][:12]}  {s['reason']}" for s in result["commits_skipped"]]
    if result["files_failed"]:
        out.append("\nfailed files:")
        out += [
            f"  {f['sha'][:12]}  {f['path']}  {f['reason']}"
            for f in result["files_failed"]
        ]
    return "\n".join(out)


def migrate_to_commit_time(result: dict) -> str:
    """Commit-time migration report as legible text (P5a.5, DR-41).
    One line per branch (ingested/skipped), then the embeddings pass and
    the per-branch coverage sweep. The per-branch ingest reports stay in
    the JSON; this render carries their totals.
    """
    out = [
        f"migrated         {result['repo']}",
        f"store            {result['store']}",
        f"parent           {result['parent_ref']}",
        (
            f"commits          ingested={result['commits_ingested']}  "
            f"skipped={result['commits_skipped']}  "
            f"failed_files={result['files_failed']}  "
            f"elapsed={result['elapsed_secs']}s"
        ),
    ]
    for branch in result["branches"]:
        report = result["branch_reports"][branch]
        out.append(
            f"  {branch}  ingested={report['commits_ingested']}  "
            f"skipped={len(report['commits_skipped'])}  "
            f"head={(report['head'] or '(unchanged)')[:12]}"
        )
    embeddings = result["embeddings"]
    if embeddings.get("embedded"):
        out.append(
            f"embeddings       generated={embeddings['generated']}  "
            f"cached={embeddings['cached']}  "
            f"total={embeddings['total']}  "
            f"persisted={embeddings['persisted']}"
        )
    else:
        out.append("embeddings       skipped")
    coverage = result.get("verify")
    if coverage is None:
        out.append("verify           skipped")
    else:
        for branch, verdict in coverage.items():
            out.append(
                f"verify[{branch}]    "
                f"{verdict['byte_coverage_pct']}% over "
                f"{verdict['total_generations']} generations"
            )
    return "\n".join(out)




def changes_between(result: dict, *, per_class: int = 25) -> str:
    """Entity diff between two instants as legible text (P2, DR-37).

    Counts first, then one capped section per class (the render caps at
    `per_class` entries with an explicit "... and N more" tail — the JSON
    report is complete). Cross-id moves name both spellings; `uncompared`
    ids are presence-only by construction.
    """
    c = result["counts"]
    head = [
        f"store            {result['store']}  (branch {result['branch']})",
        f"t1               {result['t1']}",
        f"t2               {result['t2']}",
        (
            f"scope            {result['scope']}"
            if result["scope"] is not None
            else "scope            (whole universe)"
        ),
        (
            f"changed          added={c['added']}  removed={c['removed']}  "
            f"modified={c['modified']}  moved={c['moved']}  "
            f"uncompared={c['uncompared']}  "
            f"unmodified={result['unmodified']}"
        ),
        (
            f"ids              normalized across H-11 respelling: "
            f"{result['normalized_groups']} merged groups"
            if result["normalized_ids"]
            else "ids              single spelling (no H-11 merge)"
        ),
    ]

    def fmt_span(span) -> str:
        if span is None:
            return ""
        return f"  @{span[0]}-{span[1]}"

    def entry_added(e: dict) -> str:
        return f"  + {e['id']}{fmt_span(e['span'])}"

    def entry_removed(e: dict) -> str:
        return f"  - {e['id']}{fmt_span(e['span'])}"

    def entry_modified(e: dict) -> str:
        return (
            f"  ~ {e['id']}  "
            f"{e['hash_before']} -> {e['hash_after']}"
            f"{fmt_span(e['span_after'])}"
        )

    def entry_moved(e: dict) -> str:
        if "id_before" in e:
            return (
                f"  > {e['id_before']} -> {e['id_after']}"
                f"{fmt_span(e['span_after'])}"
            )
        return f"  > {e['id']}{fmt_span(e['span_after'])}"

    sections = [
        ("added", result["added"], entry_added),
        ("removed", result["removed"], entry_removed),
        ("modified", result["modified"], entry_modified),
        ("moved", result["moved"], entry_moved),
        ("uncompared", result["uncompared"], lambda e: f"  ? {e['id']}"),
    ]
    for name, items, fmt in sections:
        head.append(f"\n{name} ({len(items)}):")
        shown = items[:per_class]
        head += [fmt(e) for e in shown]
        if len(items) > len(shown):
            head.append(f"  ... and {len(items) - len(shown)} more")
    return "\n".join(head)


# ── Edits ─────────────────────────────────────────────────────────────────

def edit(outcome: dict, apply_hint: str = "call again with `dry_run=False`") -> str:
    """A dry-run plan (ending with how to apply it) or an applied result."""
    note = f"Note: {outcome['note']}\n\n" if outcome.get("note") else ""
    plan = outcome["plan"]
    if outcome["result"] is None:
        return note + mutation_plan(plan) + f"\n**To apply:** {apply_hint}."
    return note + mutation_applied(outcome["result"], plan.unverified_sites)


def mutation_error(raw: str, *, update_file: str = "`coderadar_update_file`") -> str:
    """Translate raw engine errors into LLM-actionable prose (F10 fix)."""
    if "StaleIndex" in raw or "stale" in raw.lower():
        return (
            "## Mutation Rejected — Stale Index\n\n"
            "The file changed on disk after it was indexed, so the planned "
            "span no longer lines up. Nothing was written.\n\n"
            f"**Next step:** run {update_file} on the file (or "
            "re-analyze), then retry the mutation.\n\n"
            f"<details>Raw error: `{raw[:300]}`</details>"
        )
    if "RejectedPolicy" in raw or "policy" in raw.lower():
        return (
            "## Mutation Rejected — Policy\n\n"
            "The target path is outside the `[mutation] allow` list. "
            "Nothing was written.\n\n"
            "**Next step:** pick a target under an allowed root, or ask the "
            "user to extend the allow list.\n\n"
            f"<details>Raw error: `{raw[:300]}`</details>"
        )
    if "SpanOutOfBounds" in raw or "out of bounds" in raw.lower():
        return (
            "## Mutation Failed — Span Mismatch\n\n"
            "The computed edit span fell outside the file — likely a stale "
            "concept or an off-by-one in the planner. Nothing was written "
            "(rollback confirmed).\n\n"
            "**Next step:** update the file in the graph and retry; if it "
            "persists, report it with the entity id.\n\n"
            f"<details>Raw error: `{raw[:300]}`</details>"
        )
    if "ParseError" in raw or "syntax" in raw.lower():
        return (
            "## Mutation Failed — Syntax\n\n"
            "The edited file did not re-parse, so the change was rolled "
            "back. Nothing was written.\n\n"
            f"<details>Raw error: `{raw[:300]}`</details>"
        )
    return f"Mutation failed: {raw}"


def mutation_plan(plan: Any) -> str:
    """A MutationPlan (dry run): id, affected files, diff, unverified sites."""
    lines = [f"## Mutation Plan: `{plan.tool}` (DRY RUN)", ""]
    lines.append(f"- **Plan ID:** `{plan.id}`")
    lines.append(f"- **Affected files:** {len(plan.affected_files)}")

    if plan.diff_preview:
        lines.append("")
        lines.append("### Diff Preview")
        lines.append("```diff")
        lines.extend(plan.diff_preview.split("\n")[:60])
        if len(plan.diff_preview.split("\n")) > 60:
            lines.append("...")
        lines.append("```")

    if plan.unverified_sites:
        lines.append("")
        lines.append(
            f"⚠️ **WARNING: {len(plan.unverified_sites)} call site(s) could not be "
            f"verified/rewritten. Manual review required.**"
        )
        for site in plan.unverified_sites[:10]:
            if isinstance(site, dict):
                where = f"{site.get('file', '?')}:{site.get('line', 0)}"
                lines.append(
                    f"- `{where}` — {site.get('reason', '')}"
                    + (f" (`{site['snippet']}`)" if site.get("snippet") else "")
                )
            else:
                lines.append(f"- `{site}`")

    if plan.warnings:
        lines.append("")
        lines.append("### Warnings")
        for w in plan.warnings:
            lines.append(f"- ⚠ {w}")

    return "\n".join(lines)


def _result_field(result: Any, name: str, default: Any = None) -> Any:
    if isinstance(result, dict):
        return result.get(name, default)
    return getattr(result, name, default)


def _format_mutation_failure(failure: Any) -> str | None:
    if failure is None:
        return None
    stage = _result_field(failure, "stage", "?")
    code = _result_field(failure, "code", "?")
    message = _result_field(failure, "message", "")
    return f"{stage}/{code} — {message}"


def mutation_applied(result: Any, unverified_sites: list | None = None) -> str:
    """A MutationResult — truthfully, whatever the outcome.

    BUGS_QUIRKS #2: this used to print "## Mutation Applied" and "Graph has
    been updated" even for rejections, while a separate status line said
    RejectedPolicy and the file was untouched. The header, the state claims,
    the failure, the per-file outcomes, the sync summary, and the status now
    derive from one source. "Graph updated: yes" appears only when the
    result itself proves required synchronization completed.
    """
    status = str(_result_field(result, "status", ""))
    files_written = list(_result_field(result, "files_written", []) or [])
    syntax_errors = list(_result_field(result, "syntax_errors", []) or [])
    file_outcomes = list(_result_field(result, "files", []) or [])
    sync = _result_field(result, "sync", None)
    sync_state = _result_field(sync, "state", None) if sync is not None else None
    applied = status == "Applied"
    # A bare status without a sync object predates the sync contract. Do not
    # downgrade legacy Applied renderings; any new result carries its sync.
    graph_updated = applied and (sync is None or sync_state == "Synchronized")

    header = {
        "Applied": "## Mutation Applied",
        "RolledBack": "## Mutation Rolled Back",
        "RejectedStale": "## Mutation Rejected — Stale",
        "RejectedPolicy": "## Mutation Rejected — Policy",
        "ApplyIncomplete": "## Mutation Incomplete — Graph Sync Failed",
        "RollbackIncomplete": "## Mutation Incomplete — Rollback Incomplete",
    }.get(status, f"## Mutation Result — {status or 'Unknown'}")

    lines = [header, ""]
    lines.append(f"- **Status:** {status}")
    lines.append(f"- **File written:** {'yes' if files_written else 'no'}")
    if graph_updated:
        lines.append("- **Graph updated:** yes")
    elif applied or status in ("ApplyIncomplete", "RollbackIncomplete"):
        lines.append("- **Graph updated:** no — synchronization did not complete")
    else:
        lines.append("- **Graph updated:** no — nothing changed")
    if files_written:
        lines.append(f"- **Files written:** {len(files_written)}")
        for f in files_written:
            lines.append(f"  - `{f}`")
    failure_text = _format_mutation_failure(_result_field(result, "failure", None))
    if failure_text is None:
        failure_text = _format_mutation_failure(_result_field(result, "primary", None))
    if failure_text:
        lines.append(f"- **Failure:** {failure_text}")
    if file_outcomes:
        lines.append(f"- **File outcomes:** {len(file_outcomes)}")
        for entry in file_outcomes:
            state = _result_field(entry, "state", "?")
            name = _result_field(entry, "file", "?")
            detail = _format_mutation_failure(_result_field(entry, "error", None))
            recovery = _result_field(entry, "recovery_path", None)
            text = f"  - `{name}` — {state}"
            if detail:
                text += f" ({detail})"
            if recovery:
                text += f" [recovery: `{recovery}`]"
            lines.append(text)
    if sync is not None and sync_state is not None:
        lines.append(f"- **Sync:** {sync_state}")
        for error in list(_result_field(sync, "errors", []) or [])[:5]:
            if isinstance(error, dict):
                lines.append(
                    f"  - `{error.get('file', '?')}` — "
                    f"{error.get('stage', '?')}/{error.get('code', '?')} — "
                    f"{error.get('message', '')}"
                )
            else:
                lines.append(f"  - {error}")
        for warning in list(_result_field(sync, "warnings", []) or [])[:5]:
            if isinstance(warning, dict):
                lines.append(
                    f"  - warning `{warning.get('file', '?')}` — "
                    f"{warning.get('stage', '?')}/{warning.get('code', '?')} — "
                    f"{warning.get('message', '')}"
                )
            else:
                lines.append(f"  - warning: {warning}")
    if syntax_errors:
        lines.append(f"- **Syntax errors:** {len(syntax_errors)}")
        for e in syntax_errors[:5]:
            if isinstance(e, dict):
                where = f"{e.get('file', '?')}:{e.get('line', 0)}:{e.get('column', 0)}"
                lines.append(f"  - `{where}` — {e.get('message', '')}")
            else:
                lines.append(f"  - {e}")
    recovery_paths: list[str] = []
    for entry in file_outcomes:
        recovery = _result_field(entry, "recovery_path", None)
        if recovery and recovery not in recovery_paths:
            recovery_paths.append(str(recovery))
    backup_path = _result_field(result, "backup_path", None)
    if backup_path and backup_path not in recovery_paths:
        recovery_paths.append(str(backup_path))
    if backup_path:
        lines.append(f"- **Backup:** `{backup_path}`")
    if recovery_paths and status in ("ApplyIncomplete", "RollbackIncomplete"):
        lines.append(f"- **Recovery paths:** {len(recovery_paths)}")
        for recovery in recovery_paths:
            lines.append(f"  - `{recovery}`")
    if not applied:
        lines.append("")
        if status == "RejectedStale":
            lines.append(
                "The file changed since planning — call the plan tool again to "
                "re-read the current content, then apply the fresh plan."
            )
        elif status == "ApplyIncomplete":
            lines.append(
                "The valid source was left in place, but graph or persistence "
                "synchronization did not complete. Repair the named sync problem "
                "with `coderadar_update_file`/`coderadar_reindex`; do not blindly "
                "apply the old plan."
            )
        elif status == "RollbackIncomplete":
            lines.append(
                "Compensation or restored-state synchronization could not be proven "
                "complete. Stop automatic retries, inspect the per-file states and "
                "retained recovery paths above, recover manually, then resync."
            )
        else:
            lines.append("No changes were kept. Address the reason above and re-plan.")
    if unverified_sites:
        lines.append("")
        lines.append(
            f"⚠️ **WARNING: {len(unverified_sites)} call site(s) could not be "
            f"verified/rewritten. Manual review required.**"
        )
        for site in unverified_sites[:10]:
            lines.append(f"- `{site}`")
    return "\n".join(lines)


# ── Index lifecycle ───────────────────────────────────────────────────────

def reindex(result: dict) -> str:
    stats = result["stats"]
    lines = [
        "## Reindex Complete",
        "",
        f"- **Files:** {stats.get('file_count', 0)}",
        f"- **Modules:** {stats.get('modules', 0)}",
        f"- **Classes:** {stats.get('classes', 0)}",
        f"- **Functions:** {stats.get('functions', 0)}",
        f"- **Call edges:** {stats.get('call_edges', 0)}",
    ]
    if "embeddings" in result:
        lines.append("")
        lines.append(f"- **Embeddings generated:** {result['embeddings'].get('generated', 0)}")
        lines.append(f"- **Embeddings cached:** {result['embeddings'].get('cached', 0)}")
    elif "embeddings_error" in result:
        lines.append("")
        lines.append(f"- **Embeddings:** failed — {result['embeddings_error']}")
    # H-12: the index is sound and the counts above are real, so this is a
    # warning rather than a failure — but it must be impossible to miss.
    if "edge_persist_error" in result:
        lines += [
            "",
            (
                "> **Edges are INCOMPLETE for this generation.** Edge "
                "persistence failed part way through, so some edges were "
                "never written (concepts and blobs are unaffected). "
                "Re-run the reindex."
            ),
            "",
            f"> Engine said: `{result['edge_persist_error']}`",
        ]
    return "\n".join(lines)


def update_file(file_path: str, report: Any, from_content: bool) -> str:
    if getattr(report, "removed", False):
        return (
            f"## File Removed\n\n"
            f"- **File:** `{file_path}`\n"
            f"- Not on disk any more: {report.entities_removed} entit"
            f"{'y' if report.entities_removed == 1 else 'ies'} dropped from the graph.\n"
        )
    if not report.fully_applied:
        # tree-sitter recovers rather than failing, so the graph did take
        # entities from the file — just not reliably the ones inside the
        # region it had to recover from.
        return (
            f"## Update Incomplete\n\n"
            f"- **File:** `{file_path}`\n"
            f"- **Parse quality:** {report.parse_quality}\n"
            f"- **Parse errors:** {report.parse_errors}\n"
            f"\nThe file was indexed from a recovered parse — entities in "
            f"the broken region may be missing or wrong. Fix the syntax "
            f"and update again.\n"
        )
    return (
        f"## File Updated\n\n"
        f"- **File:** `{file_path}`\n"
        f"- Graph refreshed from {'provided content' if from_content else 'disk'}.\n"
    )


def status(result: dict) -> str:
    lines = [f"## Project: `{result['root']}`", ""]
    config = result["config"]
    lines.append(f"- **Config:** `{config}`" if config else "- **Config:** none")
    store = result["store"]
    if store:
        fresh = result.get("store_fresh")
        state = "" if fresh is None else (" (fresh)" if fresh else
                                          " (older than some source files)")
        lines.append(f"- **Store:** `{store}`{state}")
    else:
        lines.append("- **Store:** none — run `coderadar init` to create one")
    stats = result.get("stats")
    if not result["loaded"] or stats is None:
        lines.append("- **Index:** not loaded")
        return "\n".join(lines)
    age = result.get("age_seconds")
    when = "" if age is None else (f", synced {age / 60:.0f} min ago" if age >= 60
                                   else ", synced just now")
    lines.append(f"- **Index:** loaded{when}")
    lines.append("")
    for key in ("file_count", "modules", "classes", "functions", "imports",
                "constants", "call_edges"):
        if key in stats:
            lines.append(f"- {key.replace('_', ' ')}: {stats[key]}")
    return "\n".join(lines)

"""Reference documents bundled with CodeRadar.

Like the agent skills, these files live under `python-source` so maturin
copies them into the wheel. `coderadar docs <name>` prints one and the MCP
server exposes the same text as a `docs://` resource, so installed users do
not need a repo checkout to read the reference.
"""

from __future__ import annotations

from importlib.resources import files

#: Bundled references, name -> one-line description.
DOCS = {
    "query-language": "Query language and field reference (generated from the grammar).",
}

DOC_NAMES = tuple(DOCS)


class DocNotFound(KeyError):
    """Raised when a name does not identify a bundled document."""


def doc_names() -> tuple[str, ...]:
    """Names of the reference documents this distribution ships."""
    return DOC_NAMES


def doc_description(name: str) -> str:
    """One-line description for `name`."""
    try:
        return DOCS[name]
    except KeyError as exc:
        raise DocNotFound(
            f"unknown document {name!r}; available: {', '.join(DOC_NAMES)}"
        ) from exc


def doc_text(name: str) -> str:
    """Return a bundled reference document verbatim."""
    if name not in DOCS:
        raise DocNotFound(
            f"unknown document {name!r}; available: {', '.join(DOC_NAMES)}"
        )
    return (files(__name__) / f"{name}.md").read_text(encoding="utf-8")


__all__ = [
    "DOCS",
    "DOC_NAMES",
    "DocNotFound",
    "doc_description",
    "doc_names",
    "doc_text",
]

"""CodeRadar v3.6 — Mutation Tool Router (§11.2)

Routes LLM tool calls to the appropriate Rust planner: replace_entity_body,
update_signature, rename_symbol, create_entity.

P4 wire-or-cut verdict (v0.12): KEPT as the P2 tool-call seam. Tested
but unwired today; P2 skills route agent tool calls through
ToolRouter.route — cutting it now would be churn, not hygiene.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass
from typing import Any

import structlog

logger = structlog.get_logger(__name__)


@dataclass
class ToolCall:
    """An LLM tool call with parsed function selection and arguments."""
    tool_name: str
    arguments: dict[str, Any]
    call_id: str


@dataclass
class ToolResult:
    """Result of executing a mutation tool call."""
    call_id: str
    success: bool
    result: Any
    error: str | None = None


class ToolRouter:
    """Routes LLM tool calls to the appropriate mutation planner.

    The four tools (§11.2):
    - replace_entity_body: Replace a function/method body
    - update_signature: Update signature + cascade to call sites
    - rename_symbol: Rename across the codebase
    - create_entity: Create a new entity at an anchor point
    """

    def __init__(self, graph: Any = None, dry_run: bool = True):
        self.graph = graph
        self.dry_run = dry_run

    def route(self, call: ToolCall) -> ToolResult:
        """Route a tool call to the appropriate planner."""
        try:
            if call.tool_name == "replace_entity_body":
                return self._handle_body_replacement(call)
            elif call.tool_name == "update_signature":
                return self._handle_signature_update(call)
            elif call.tool_name == "rename_symbol":
                return self._handle_rename(call)
            elif call.tool_name == "create_entity":
                return self._handle_create_entity(call)
            else:
                return ToolResult(
                    call_id=call.call_id,
                    success=False,
                    result=None,
                    error=f"Unknown tool: {call.tool_name}",
                )
        except Exception as e:  # noqa: BLE001 - tool boundary must return failure, never raise
            logger.error("tool_call_error", tool=call.tool_name,
                          error=str(e))
            return ToolResult(
                call_id=call.call_id,
                success=False,
                result=None,
                error=str(e),
            )

    @staticmethod
    def _mutation_payload(result: Any, extra: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = asdict(result)
        if extra:
            payload.update(extra)
        return payload

    @staticmethod
    def _mutation_error(result: Any) -> str | None:
        if result.status == "Applied":
            return None
        parts: list[str] = []
        failure = result.failure or result.primary
        if failure is not None:
            parts.append(f"{failure.stage}/{failure.code} — {failure.message}")
        for entry in result.sync.errors:
            parts.append(f"{entry.get('stage', '?')}/{entry.get('code', '?')} — {entry.get('message', '')}")
        parts.extend(str(error) for error in result.syntax_errors)
        return "\n".join(part for part in parts if part) or f"mutation did not apply: {result.status}"

    def _handle_body_replacement(self, call: ToolCall) -> ToolResult:
        """replace_entity_body: entity_id, new_body, expected_hash?"""
        args = call.arguments
        entity_id = args["entity_id"]
        new_body = args["new_body"]
        expected_hash = args.get("expected_hash")

        if self.graph:
            plan = self.graph.plan_replace_body(
                entity_id, new_body, expected_hash, dry_run=self.dry_run,
            )
            if not self.dry_run:
                result = self.graph.apply(plan)
                return ToolResult(
                    call_id=call.call_id,
                    success=result.status == "Applied",
                    result=self._mutation_payload(result),
                    error=self._mutation_error(result),
                )
            return ToolResult(
                call_id=call.call_id, success=True,
                result={"plan": plan.id, "diff_preview": plan.diff_preview},
            )

        return ToolResult(call_id=call.call_id, success=False, result=None,
                          error="No graph available")

    def _handle_signature_update(self, call: ToolCall) -> ToolResult:
        """update_signature: entity_id, new_signature, call_site_values?
                            inject_defaults?"""
        args = call.arguments
        entity_id = args["entity_id"]
        new_signature = args["new_signature"]
        call_site_values = args.get("call_site_values", {})
        inject_defaults = args.get("inject_defaults", False)

        if self.graph:
            plan = self.graph.plan_update_signature(
                entity_id, new_signature, call_site_values,
                inject_defaults, dry_run=self.dry_run,
            )
            if not self.dry_run:
                result = self.graph.apply(plan)
                return ToolResult(
                    call_id=call.call_id,
                    success=result.status == "Applied",
                    result=self._mutation_payload(result, {"unverified_sites": plan.unverified_sites}),
                    error=self._mutation_error(result),
                )
            return ToolResult(
                call_id=call.call_id, success=True,
                result={
                    "plan": plan.id,
                    "affected_files": plan.affected_files,
                    "unverified_sites": plan.unverified_sites,
                },
            )

        return ToolResult(call_id=call.call_id, success=False, result=None,
                          error="No graph available")

    def _handle_rename(self, call: ToolCall) -> ToolResult:
        """rename_symbol: entity_id, new_name, include_strings?"""
        args = call.arguments
        entity_id = args["entity_id"]
        new_name = args["new_name"]
        include_strings = args.get("include_strings", False)

        if self.graph:
            plan = self.graph.plan_rename(
                entity_id, new_name, include_strings, dry_run=self.dry_run,
            )
            if not self.dry_run:
                result = self.graph.apply(plan)
                return ToolResult(
                    call_id=call.call_id,
                    success=result.status == "Applied",
                    result=self._mutation_payload(result),
                    error=self._mutation_error(result),
                )
            return ToolResult(
                call_id=call.call_id, success=True,
                result={
                    "plan": plan.id,
                    "affected_files": plan.affected_files,
                    "diff_preview": plan.diff_preview,
                },
            )

        return ToolResult(call_id=call.call_id, success=False, result=None,
                          error="No graph available")

    def _handle_create_entity(self, call: ToolCall) -> ToolResult:
        """create_entity: target_file, anchor, code"""
        args = call.arguments
        target_file = args["target_file"]
        anchor = args.get("anchor", "end")
        code = args["code"]

        if self.graph:
            plan = self.graph.plan_create_entity(
                target_file, anchor, code, dry_run=self.dry_run,
            )
            if not self.dry_run:
                result = self.graph.apply(plan)
                return ToolResult(
                    call_id=call.call_id,
                    success=result.status == "Applied",
                    result=self._mutation_payload(result, {"warnings": plan.warnings}),
                    error=self._mutation_error(result),
                )
            return ToolResult(
                call_id=call.call_id, success=True,
                result={
                    "plan": plan.id,
                    "affected_files": plan.affected_files,
                    "warnings": plan.warnings,
                },
            )

        return ToolResult(call_id=call.call_id, success=False, result=None,
                          error="No graph available")

    # Mutation policy is enforced in MutationEngine::apply on the Rust side —
    # the trust boundary is the FFI, not this router, since apply_mutation
    # accepts an arbitrary plan from any caller. A stub here read as
    # implemented and returned True unconditionally; it was never called.

"""CodeRadar v3.6 — Query Cache (§7.3)

LRU cache for Macrame query results, keyed on (method, params, graph_epoch).
Invalidated on every write.
"""

from __future__ import annotations

import hashlib
import json
import time
from collections.abc import Callable
from functools import wraps
from typing import Any


class QueryCache:
    """Thread-safe LRU cache for Macrame query results.

    Cache entries keyed on (method, params, graph_epoch).
    TTL and max-size bounded. Invalidated on every graph write.
    """

    def __init__(self, max_size: int = 256, ttl_seconds: int = 300):
        self._max_size = max_size
        self._ttl_seconds = ttl_seconds
        self._cache: dict[str, _CacheEntry] = {}

    def get(self, key: str) -> Any | None:
        entry = self._cache.get(key)
        if entry is None:
            return None
        # >=, not >: a ttl of 0 means "never valid", and on Windows two
        # monotonic() reads around a set() can be equal — a strict compare
        # made ttl=0 entries immortal there while Linux timers masked it.
        if time.monotonic() - entry.timestamp >= self._ttl_seconds:
            del self._cache[key]
            return None
        return entry.value

    def set(self, key: str, value: Any) -> None:
        if len(self._cache) >= self._max_size:
            oldest = min(self._cache, key=lambda k: self._cache[k].timestamp)
            del self._cache[oldest]
        self._cache[key] = _CacheEntry(value, time.monotonic())

    def invalidate(self) -> None:
        self._cache.clear()

    def prune_expired(self) -> int:
        now = time.monotonic()
        # Same >= as get(): ttl=0 expires everything, deterministically.
        expired = [
            k for k, v in self._cache.items()
            if now - v.timestamp >= self._ttl_seconds
        ]
        for k in expired:
            del self._cache[k]
        return len(expired)

    @staticmethod
    def make_key(method: str, params: dict[str, Any],
                 graph_epoch: int) -> str:
        param_str = json.dumps(params, sort_keys=True)
        raw = f"{method}|{param_str}|{graph_epoch}"
        return hashlib.sha256(raw.encode()).hexdigest()[:32]

    def __len__(self) -> int:
        return len(self._cache)


class _CacheEntry:
    __slots__ = ("timestamp", "value")

    def __init__(self, value: Any, timestamp: float):
        self.value = value
        self.timestamp = timestamp


_default_cache = QueryCache()


def cached_query(func: Callable) -> Callable:
    """Decorator that caches Macrame query results."""

    @wraps(func)
    def wrapper(*args, **kwargs):
        cache = _default_cache
        graph_epoch = kwargs.pop("_epoch", 0)
        key = QueryCache.make_key(
            func.__name__,
            {"args": str(args)[:200], "kwargs": str(kwargs)[:200]},
            graph_epoch,
        )
        cached = cache.get(key)
        if cached is not None:
            return cached
        result = func(*args, **kwargs, _epoch=graph_epoch)
        cache.set(key, result)
        return result

    return wrapper

"""CodeRadar v0.5 — ASP.NET Framework Resolver (F.12 Phase 1)

Handles ASP.NET Core attribute-based route registrations for C#.
Produces synthetic route nodes and handler edges.

ASP.NET patterns:
  [HttpGet("/users")]                  → GET /users
  [HttpPost("/users")]                 → POST /users
  [HttpPut("/users/{id}")]             → PUT /users/{id}
  [HttpDelete("/users/{id}")]          → DELETE /users/{id}
  [HttpPatch("/users/{id}")]           → PATCH /users/{id}
  [Route("/api/[controller]")] on class → base path prefix
  [ApiController]                      → marks controller class
  Minimal API: app.MapGet("/users", handler) → .NET 6+
"""

from __future__ import annotations

import re
from pathlib import Path
from typing import Any

from coderadar.excludes import iter_project_files as _iter_files

from .base import FrameworkExtraction, FrameworkResolver, SyntheticEdge, SyntheticNode

# ── Regex patterns ──────────────────────────────────────────────────────────

# Class declaration with optional [Route] base path:
# [ApiController]
# [Route("api/[controller]")]
# public class UsersController : ControllerBase {
_CLASS_DECL_RE = re.compile(
    r'\[ApiController\]\s*\n'
    r'(?:\s*\[Route\s*\(\s*"(.*?)"\s*\)\]\s*\n)?'
    r'(?:public|private|protected|internal)\s+(?:partial\s+)?class\s+(\w+)',
    re.MULTILINE,
)

# HTTP method attribute: [HttpGet("/path")], [HttpPost("/path")], etc.
# Also handles bare [HttpGet] (inherits class base path)
_HTTP_ATTRIBUTE_RE = re.compile(
    r'\[(HttpGet|HttpPost|HttpPut|HttpDelete|HttpPatch|HttpHead|HttpOptions)'
    r'\s*\(\s*"([^"]*)"\s*\)'
    r'|\[(HttpGet|HttpPost|HttpPut|HttpDelete|HttpPatch|HttpHead|HttpOptions)\s*\]',
    re.IGNORECASE,
)

# Minimal API: app.MapGet("/users", handler), app.MapPost(...)
_MINIMAL_API_RE = re.compile(
    r'(?:app|group)\.'
    r'(MapGet|MapPost|MapPut|MapDelete|MapPatch)'
    r'\s*\(\s*"([^"]*)"\s*,\s*'
    r'([^)]+)',
    re.IGNORECASE,
)

# Method declaration: public IActionResult MethodName(
_METHOD_DECL_RE = re.compile(
    r'(?:public|private|protected|internal)\s+(?:async\s+)?'
    r'(?:\w+(?:<[^>]*>)?\s*)?(\w+)\s*\(',
    re.MULTILINE,
)

# Route token replacement: [controller] → controller class name without "Controller"
_ROUTE_TOKEN_RE = re.compile(r'\[controller\]', re.IGNORECASE)

_METHOD_MAP: dict[str, str] = {
    'HttpGet': 'GET', 'HttpPost': 'POST', 'HttpPut': 'PUT',
    'HttpDelete': 'DELETE', 'HttpPatch': 'PATCH',
    'HttpHead': 'HEAD', 'HttpOptions': 'OPTIONS',
    'MapGet': 'GET', 'MapPost': 'POST', 'MapPut': 'PUT',
    'MapDelete': 'DELETE', 'MapPatch': 'PATCH',
}

_HANDLER_DIRS = ['Controllers', 'Controllers/Api', 'Endpoints', 'Handlers']
_SERVICE_DIRS = ['Services', 'Repositories', 'Data', 'Models', 'Middleware']


class AspNetResolver(FrameworkResolver):
    """ASP.NET Core attribute-based and Minimal API route resolver for C#."""

    @property
    def name(self) -> str:
        return "aspnet"

    def detect(self, project_root: Path) -> bool:
        markers = list(_iter_files(project_root, suffixes=(".csproj", ".sln")))
        if not markers:
            # Fallback: grep for ASP.NET attributes in .cs files
            for path in list(_iter_files(project_root, suffixes=(".cs",)))[:200]:
                try:
                    content = path.read_text(encoding="utf-8")
                    if '[ApiController]' in content or '[HttpGet' in content:
                        return True
                except (OSError, UnicodeDecodeError):
                    pass
            return False

        for path in markers:
                try:
                    content = path.read_text(encoding="utf-8")
                    if 'Microsoft.NET.Sdk.Web' in content or 'Microsoft.AspNetCore' in content:
                        return True
                except (OSError, UnicodeDecodeError):
                    pass
        return False

    def claims_reference(self, name: str) -> bool:
        parts = name.rsplit(".", 1)[-1]
        return parts.endswith(
            ("Controller", "Service", "Repository", "Handler", "Endpoint", "Middleware")
        )

    def extract(self, file_path: str, source: str) -> FrameworkExtraction:
        nodes: list[SyntheticNode] = []
        edges: list[SyntheticEdge] = []

        if not file_path.endswith('.cs'):
            return FrameworkExtraction(file_path=file_path)

        # ── Find per-class regions ──
        class_regions = list(_find_class_regions(source))

        # ── Pattern 1: [HttpGet] style attributes ──
        for match in _HTTP_ATTRIBUTE_RE.finditer(source):
            # Groups 1+2: with path; Groups 3+4: bare attribute
            ann_name = match.group(1) or match.group(3)
            if not ann_name:
                continue
            path_fragment = match.group(2) or ""
            method = _METHOD_MAP.get(ann_name, 'GET')

            match_pos = match.start()
            class_name, base_path = _class_context(match_pos, class_regions)
            full_path = self._join_paths(base_path, path_fragment, class_name)

            handler_name = _find_handler_method(source, match.end())
            line_no = source[:match_pos].count('\n') + 1
            route_id = f"aspnet:route:{file_path}:{line_no}:{method}:{full_path}"

            nodes.append(SyntheticNode(
                id=route_id, name=f"{method} {full_path}", kind="route",
                file_path=file_path,
                metadata={
                    "language": "csharp", "framework": "aspnet",
                    "method": method, "path": full_path,
                    "line": line_no, "annotation": ann_name, "class": class_name,
                },
            ))
            if handler_name:
                qualified = f"{class_name}.{handler_name}" if class_name else handler_name
                edges.append(SyntheticEdge(
                    source_id=route_id, target_id=qualified, kind="handles",
                    metadata={
                        "synthesizedBy": "aspnet-resolver",
                        "line": line_no, "method": method,
                    },
                ))

        # ── Pattern 2: Minimal API (app.MapGet, etc.) ──
        for match in _MINIMAL_API_RE.finditer(source):
            map_name = match.group(1)
            route_path = match.group(2)
            handler_expr = match.group(3).strip()
            method = _METHOD_MAP.get(map_name, 'GET')

            line_no = source[:match.start()].count('\n') + 1
            route_id = f"aspnet:route:{file_path}:{line_no}:{method}:{route_path}"

            nodes.append(SyntheticNode(
                id=route_id, name=f"{method} {route_path}", kind="route",
                file_path=file_path,
                metadata={
                    "language": "csharp", "framework": "aspnet-minimal",
                    "method": method, "path": route_path,
                    "line": line_no,
                },
            ))

            handler_name = _parse_minimal_handler(handler_expr)
            if handler_name:
                edges.append(SyntheticEdge(
                    source_id=route_id, target_id=handler_name, kind="handles",
                    metadata={
                        "synthesizedBy": "aspnet-resolver",
                        "line": line_no, "method": method,
                    },
                ))

        return FrameworkExtraction(file_path=file_path, nodes=nodes, edges=edges)

    def resolve(
        self, ref_name: str, candidates: list[dict[str, Any]],
    ) -> dict[str, Any] | None:
        if not candidates:
            return None
        pref_dirs = _HANDLER_DIRS + _SERVICE_DIRS
        for result in candidates:
            fp = result.get("file_path", "")
            for d in pref_dirs:
                if f"/{d}/" in fp or f"\\{d}\\" in fp:
                    result["confidence"] = 0.85
                    return result
        result = candidates[0]
        result["confidence"] = 0.65
        return result

    @staticmethod
    def _join_paths(base: str, fragment: str, class_name: str | None = None) -> str:
        resolved_base = _resolve_route_tokens(base, class_name)
        if not resolved_base:
            return _resolve_route_tokens(fragment, class_name)
        if not fragment:
            return resolved_base
        resolved_frag = _resolve_route_tokens(fragment, class_name)
        if resolved_frag.startswith('/') and resolved_base.endswith('/'):
            return resolved_base + resolved_frag[1:]
        if not resolved_frag.startswith('/') and not resolved_base.endswith('/'):
            return resolved_base + '/' + resolved_frag
        return resolved_base + resolved_frag


# ── Helpers ─────────────────────────────────────────────────────────────────


def _resolve_route_tokens(path: str, class_name: str | None) -> str:
    """Replace [controller] token with class name minus 'Controller' suffix."""
    if not path or not class_name:
        return path
    if '[controller]' in path:
        short_name = class_name
        short_name = short_name.removesuffix('Controller')
        path = _ROUTE_TOKEN_RE.sub(short_name.lower(), path)
    return path


def _find_class_regions(source: str) -> list[tuple[str | None, str, int, int]]:
    """Find all [ApiController] classes and their [Route] base paths."""
    regions: list[tuple[str | None, str, int, int]] = []
    for m in _CLASS_DECL_RE.finditer(source):
        base_path = m.group(1) or ""
        class_name = m.group(2)
        start = m.start()
        end = len(source)
        if regions:
            prev = regions[-1]
            regions[-1] = (prev[0], prev[1], prev[2], start)
        regions.append((class_name, base_path, start, end))
    return regions


def _class_context(pos: int, regions: list[tuple[str | None, str, int, int]]) -> tuple[str | None, str]:
    for name, base, start, end in reversed(regions):
        if start <= pos < end:
            return name, base
    return None, ""


def _find_handler_method(source: str, after_pos: int) -> str | None:
    window = source[after_pos:after_pos + 500]
    m = _METHOD_DECL_RE.search(window)
    return m.group(1) if m else None


def _parse_minimal_handler(expr: str) -> str | None:
    """Parse a minimal API handler expression.

    Patterns:
      GetUsers           → GetUsers
      new { ... }        → None (anonymous)
      async (ctx) => ... → None (lambda)
    """
    expr = expr.strip().rstrip(',); ')
    if expr.startswith('new '):
        return None
    if '=>' in expr:
        return None
    m = re.search(r'(\w+)$', expr)
    return m.group(1) if m else None

"""Django Framework Resolver (§28.2)

Detects Django projects (manage.py), extracts URL routing from urls.py
patterns, resolves Model/View/Form naming conventions.
"""

from __future__ import annotations

import ast
from pathlib import Path
from typing import Any

from .base import (
    FrameworkExtraction,
    FrameworkResolver,
    SyntheticEdge,
    SyntheticNode,
)


class DjangoResolver(FrameworkResolver):
    """Resolves Django-specific constructs:

    - URL routing: path(), re_path(), url() → route nodes + handler edges
    - Model references: *Model → models.py classes
    - View references: *View → views.py functions
    - Form references: *Form → forms.py classes
    - Admin registration: admin.site.register()
    """

    ROUTE_CALLS = frozenset({"path", "re_path", "url"})
    MODEL_SUFFIX = "Model"
    VIEW_SUFFIX = "View"
    FORM_SUFFIX = "Form"

    @property
    def name(self) -> str:
        return "django"

    def detect(self, project_root: Path) -> bool:
        return (project_root / "manage.py").exists()

    def claims_reference(self, name: str) -> bool:
        parts = name.rsplit(".", 1)[-1]  # bare class name
        return parts.endswith(
            (self.MODEL_SUFFIX, self.VIEW_SUFFIX, self.FORM_SUFFIX)
        ) or name in ("objects", "DoesNotExist", "MultipleObjectsReturned")

    def extract(self, file_path: str, source: str) -> FrameworkExtraction:
        result = FrameworkExtraction(file_path=file_path)

        try:
            tree = ast.parse(source)
        except SyntaxError:
            return result

        for node in ast.walk(tree):
            # URL patterns in urlpatterns lists
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name) and target.id == "urlpatterns":
                        result.nodes.extend(self._extract_routes(node.value))
                        result.edges.extend(self._extract_route_edges(
                            node.value, file_path))

            # admin.site.register(Model)
            if isinstance(node, ast.Call):
                result.edges.extend(self._extract_admin_register(node, file_path))
                # DRF router.register(prefix, ViewSet)
                result.edges.extend(self._extract_drf_router(node, file_path))

        return result

    def _extract_routes(self, value: ast.expr) -> list[SyntheticNode]:
        """Extract SyntheticNode for each path()/re_path() call."""
        nodes: list[SyntheticNode] = []
        if not isinstance(value, (ast.List, ast.Tuple)):
            return nodes

        for elem in value.elts:
            if isinstance(elem, ast.Call):
                call_name = self._get_call_name(elem)
                if call_name in self.ROUTE_CALLS:
                    route = self._parse_route_call(elem)
                    if route:
                        nodes.append(route)

        return nodes

    def _extract_route_edges(
        self, value: ast.expr, file_path: str,
    ) -> list[SyntheticEdge]:
        """Create edges from route nodes to their view handlers."""
        edges: list[SyntheticEdge] = []
        if not isinstance(value, (ast.List, ast.Tuple)):
            return edges

        for idx, elem in enumerate(value.elts):
            if isinstance(elem, ast.Call):
                call_name = self._get_call_name(elem)
                if call_name in self.ROUTE_CALLS:
                    handler = self._get_route_handler(elem)
                    if handler:
                        route_id = f"{file_path}::__url_pattern_{idx}"
                        handler_id = f"{file_path}::{handler}"
                        edges.append(SyntheticEdge(
                            source_id=route_id,
                            target_id=handler_id,
                            kind="handles",
                            metadata={
                                "synthesized_by": self.name,
                                "framework": "django",
                            },
                        ))

        return edges

    def _extract_admin_register(
        self, node: ast.Call, file_path: str,
    ) -> list[SyntheticEdge]:
        """Extract edges from admin.site.register(Model)."""
        edges: list[SyntheticEdge] = []

        # Check for admin.site.register pattern
        if (
            isinstance(node.func, ast.Attribute)
            and node.func.attr == "register"
            and isinstance(node.func.value, ast.Attribute)
            and node.func.value.attr == "site"
            and isinstance(node.func.value.value, ast.Name)
            and node.func.value.value.id == "admin"
            and node.args
        ):
                model_name = self._get_name(node.args[0])
                if model_name:
                    edges.append(SyntheticEdge(
                        source_id=f"{file_path}::admin",
                        target_id=f"{file_path}::{model_name}",
                        kind="registers",
                        metadata={
                            "synthesized_by": self.name,
                            "framework": "django",
                            "admin_model": model_name,
                        },
                    ))

        return edges

    def _extract_drf_router(
        self, node: ast.Call, file_path: str,
    ) -> list[SyntheticEdge]:
        """Extract edges from DRF router.register(prefix, ViewSet).

        Pattern: router.register(r'users/', UserViewSet, basename='user')
        """
        edges: list[SyntheticEdge] = []
        call_name = self._get_call_name(node)
        if call_name != "register":
            return edges
        # Ensure it's called on a router object (router.register, not just .register)
        if not isinstance(node.func, ast.Attribute):
            return edges
        if len(node.args) < 2:
            return edges
        prefix = self._get_string_value(node.args[0])
        viewset = self._get_name(node.args[1])
        if prefix and viewset:
            edges.append(SyntheticEdge(
                source_id=f"django:route:{prefix}",
                target_id=f"{file_path}::{viewset}",
                kind="handles",
                metadata={
                    "synthesized_by": self.name,
                    "framework": "django",
                    "pattern": prefix,
                    "viewset": viewset,
                },
            ))
        return edges

    def _parse_route_call(self, call: ast.Call) -> SyntheticNode | None:
        """Parse a path()/re_path() call into a SyntheticNode."""
        if not call.args:
            return None

        route_pattern = self._get_string_value(call.args[0])
        if not route_pattern:
            return None

        metadata: dict[str, Any] = {"pattern": route_pattern}

        for kw in call.keywords:
            if kw.arg == "name":
                metadata["route_name"] = self._get_string_value(kw.value)
            elif kw.arg == "kwargs":
                metadata["default_kwargs"] = "..."

        return SyntheticNode(
            id=f"django:route:{route_pattern}",
            name=route_pattern,
            kind="route",
            file_path="__django_urls__",
            metadata=metadata,
        )

    def _get_route_handler(self, call: ast.Call) -> str | None:
        """Get the view handler name from a path() call.

        Strips .as_view() suffix for Django class-based views.
        """
        if len(call.args) >= 2:
            handler = self._get_name(call.args[1])
            return self._strip_as_view(handler)
        for kw in call.keywords:
            if kw.arg == "view":
                handler = self._get_name(kw.value)
                return self._strip_as_view(handler)
        return None

    @staticmethod
    def _strip_as_view(handler: str | None) -> str | None:
        """Remove .as_view() suffix from Django CBV handlers.

        views.MyView.as_view → views.MyView
        """
        if handler and handler.endswith(".as_view"):
            return handler[:-len(".as_view")]
        return handler

    def resolve(
        self, ref_name: str, candidates: list[dict[str, Any]],
    ) -> dict[str, Any] | None:
        """Resolve Django naming conventions against search candidates.

        *Model → prefer matches in models.py
        *View → prefer matches in views.py
        """
        if not candidates:
            return None

        suffix = None
        search_dir = None

        parts = ref_name.rsplit(".", 1)[-1]
        if parts.endswith(self.MODEL_SUFFIX):
            suffix = self.MODEL_SUFFIX
            search_dir = "models"
        elif parts.endswith(self.VIEW_SUFFIX):
            suffix = self.VIEW_SUFFIX
            search_dir = "views"
        elif parts.endswith(self.FORM_SUFFIX):
            suffix = self.FORM_SUFFIX
            search_dir = "forms"

        if not suffix:
            return None

        base_name = parts[:-len(suffix)] if parts != suffix else parts
        from .resolution import prefer_in_dir
        return prefer_in_dir(candidates, base_name, search_dir, confidence=0.85)

    # ── AST Helpers ─────────────────────────────────────────────────

    @staticmethod
    def _get_call_name(call: ast.Call) -> str | None:
        """Get the function name from a call."""
        if isinstance(call.func, ast.Name):
            return call.func.id
        if isinstance(call.func, ast.Attribute):
            return call.func.attr
        return None

    @staticmethod
    def _get_name(node: ast.expr) -> str | None:
        """Get a dotted name from an AST expression."""
        if isinstance(node, ast.Name):
            return node.id
        if isinstance(node, ast.Attribute):
            base = DjangoResolver._get_name(node.value)
            return f"{base}.{node.attr}" if base else node.attr
        if isinstance(node, ast.Call):
            return DjangoResolver._get_name(node.func)
        return None

    @staticmethod
    def _get_string_value(node: ast.expr) -> str | None:
        """Get a string literal value."""
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            return node.value
        return None

"""CodeRadar v3.6 — Module Export Resolution (§6.3a, F.4)

Handles `__all__` detection for Python modules. Supports:
- `__all__ = ["foo", "bar"]` (literal list)
- `__all__ += [...]` (augmented assignment)
- `__all__.extend([...])` (method call)

Based on CodeGraph's export resolution pattern (python.rs).
Copyright (c) 2024 Colby McHenry — MIT License
<https://github.com/colbymchenry/codegraph>
"""

from __future__ import annotations

import ast


def extract_all_exports(source: str) -> list[str] | None:
    """Extract __all__ exports from Python source.

    Returns None if __all__ cannot be statically determined.
    """
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return None

    names: list[str] = []
    all_found = False

    for node in ast.walk(tree):
        # __all__ = ["foo", "bar"]
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "__all__":
                    all_found = True
                    names.extend(_extract_list_literals(node.value))

        # __all__ += ["baz"]
        if (
            isinstance(node, ast.AugAssign)
            and isinstance(node.target, ast.Name)
            and node.target.id == "__all__"
        ):
                all_found = True
                names.extend(_extract_list_literals(node.value))

        # __all__.extend(["qux"])
        if isinstance(node, ast.Call) and (
                isinstance(node.func, ast.Attribute)
                and node.func.attr == "extend"
                and isinstance(node.func.value, ast.Name)
                and node.func.value.id == "__all__"
            ):
                all_found = True
                if node.args:
                    names.extend(_extract_list_literals(node.args[0]))

        # __all__.append("single")
        if isinstance(node, ast.Call) and (
                isinstance(node.func, ast.Attribute)
                and node.func.attr == "append"
                and isinstance(node.func.value, ast.Name)
                and node.func.value.id == "__all__"
                and node.args
            ):
                all_found = True
                if isinstance(node.args[0], ast.Constant) and isinstance(
                    node.args[0].value, str
                ):
                    names.append(node.args[0].value)

    if not all_found:
        return None

    return list(dict.fromkeys(names))  # deduplicate, preserve order


def _extract_list_literals(node: ast.expr) -> list[str]:
    """Extract string literals from a list/tuple node."""
    names: list[str] = []
    if isinstance(node, (ast.List, ast.Tuple)):
        for elem in node.elts:
            if isinstance(elem, ast.Constant) and isinstance(elem.value, str):
                names.append(elem.value)
    return names

"""FastAPI Framework Resolver (§28.2)

Detects FastAPI projects by scanning for APIRouter imports, FastAPI app
instantiation, and route decorator patterns. Extracts:
- @app.get()/post()/put()/delete() → route nodes + handler edges
- @router.get()/post()/... → router route nodes
- Dependency injection chains: Depends() parameter annotations
- app.include_router(router) → router registration edges
"""

from __future__ import annotations

import ast
from pathlib import Path
from typing import Any

from coderadar.excludes import iter_project_files as _iter_files

from .base import (
    FrameworkExtraction,
    FrameworkResolver,
    SyntheticEdge,
    SyntheticNode,
)


class FastAPIResolver(FrameworkResolver):
    """Resolves FastAPI-specific constructs:

    - Route registration: @app.get('/path'), @router.post('/path') → handler edges
    - Router include: app.include_router(router) → module edges
    - Dependency injection: Depends(SomeDep) → dependency edges
    - WebSocket endpoints: @app.websocket('/ws')
    - Middleware: app.add_middleware()
    """

    ROUTE_METHODS = frozenset({
        "get", "post", "put", "delete", "patch", "options", "head",
        "websocket", "api_route", "on_event",
    })

    @property
    def name(self) -> str:
        return "fastapi"

    def detect(self, project_root: Path) -> bool:
        for py_file in _iter_files(project_root, suffixes=(".py",)):
            if py_file.name.startswith("__"):
                continue
            try:
                content = py_file.read_text(encoding="utf-8")
                if "fastapi" in content.lower():
                    return True
            except (OSError, UnicodeDecodeError):
                pass
        return False

    def claims_reference(self, name: str) -> bool:
        parts = name.rsplit(".", 1)[-1]
        return any(
            kw in parts.lower()
            for kw in ("fastapi", "apirouter", "depends", "query",
                       "path_param", "body_param", "header_param")
        )

    def extract(self, file_path: str, source: str) -> FrameworkExtraction:
        result = FrameworkExtraction(file_path=file_path)

        try:
            tree = ast.parse(source)
        except SyntaxError:
            return result

        app_name = self._detect_app_name(tree)

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                # Route decorators
                route_nodes = self._extract_routes(node, app_name, file_path)
                result.nodes.extend(route_nodes)
                for rn in route_nodes:
                    result.edges.append(SyntheticEdge(
                        source_id=rn.id,
                        target_id=f"{file_path}::{node.name}",
                        kind="handles",
                        metadata={
                            "synthesized_by": self.name,
                            "framework": "fastapi",
                            "methods": rn.metadata.get("methods", ["GET"]),
                        },
                    ))

                # Dependency injection from function parameters
                dep_edges = self._extract_dependencies(
                    node, file_path)
                result.edges.extend(dep_edges)

            if isinstance(node, ast.Call):
                # app.include_router()
                router_edges = self._extract_router_include(node, file_path)
                result.edges.extend(router_edges)

        return result

    def _detect_app_name(self, tree: ast.Module) -> str | None:
        """Find the FastAPI app variable name."""
        for node in ast.walk(tree):
            if (
                isinstance(node, ast.Assign)
                and isinstance(node.value, ast.Call)
                and self._get_call_name(node.value) == "FastAPI"
            ):
                    for target in node.targets:
                        if isinstance(target, ast.Name):
                            return target.id
        return None

    def _extract_routes(
        self,
        func_node: ast.FunctionDef,
        app_name: str | None,
        file_path: str,
    ) -> list[SyntheticNode]:
        """Extract route nodes from function decorators."""
        nodes: list[SyntheticNode] = []

        for decorator in func_node.decorator_list:
            if not isinstance(decorator, ast.Call):
                continue

            decorator_name = self._get_decorator_attr(decorator)
            if decorator_name not in self.ROUTE_METHODS:
                continue

            if not decorator.args:
                continue

            path = self._get_string_value(decorator.args[0])
            if not path:
                continue

            metadata: dict[str, Any] = {
                "pattern": path,
                "handler": func_node.name,
            }

            if decorator_name == "api_route":
                for kw in decorator.keywords:
                    if kw.arg == "methods":
                        methods = self._get_list_value(kw.value)
                        if methods:
                            metadata["methods"] = methods
                    elif kw.arg == "response_model":
                        model = self._get_name(kw.value)
                        if model:
                            metadata["response_model"] = model
            else:
                metadata["methods"] = [decorator_name.upper()]

            # Extract response_model, status_code, etc.
            for kw in decorator.keywords:
                if kw.arg == "response_model":
                    model = self._get_name(kw.value)
                    if model:
                        metadata["response_model"] = model
                elif kw.arg == "status_code":
                    if isinstance(kw.value, ast.Constant):
                        metadata["status_code"] = kw.value.value

            nodes.append(SyntheticNode(
                id=f"fastapi:route:{file_path}:{path}",
                name=path,
                kind="route",
                file_path=file_path,
                metadata=metadata,
            ))

        return nodes

    def _extract_dependencies(
        self, func_node: ast.FunctionDef | ast.AsyncFunctionDef, file_path: str,
    ) -> list[SyntheticEdge]:
        """Extract dependency injection edges from function parameter defaults.

        Handles: Depends(some_callable) in parameter defaults.
        """
        edges: list[SyntheticEdge] = []

        # args.defaults holds the last N defaults
        defaults = func_node.args.defaults
        num_defaults = len(defaults)
        if num_defaults == 0:
            return edges

        args_with_defaults = func_node.args.args[-num_defaults:]

        for arg, default in zip(args_with_defaults, defaults):
            dep_name = self._find_depends_call(default)
            if dep_name:
                edges.append(SyntheticEdge(
                    source_id=f"{file_path}::{func_node.name}",
                    target_id=f"{file_path}::{dep_name}",
                    kind="depends_on",
                    metadata={
                        "synthesized_by": self.name,
                        "framework": "fastapi",
                        "parameter": arg.arg,
                    },
                ))

        return edges

    def _find_depends_call(self, annotation: ast.expr) -> str | None:
        """Find a Depends() call within an annotation AST node.

        Handles:
          Depends(get_db)
          Annotated[DB, Depends(get_db)]
        """
        for node in ast.walk(annotation):
            if isinstance(node, ast.Call):
                call_name = self._get_call_name(node)
                if call_name == "Depends" and node.args:
                    return self._get_name(node.args[0])
        return None

    def _extract_router_include(
        self, node: ast.Call, file_path: str,
    ) -> list[SyntheticEdge]:
        """Extract edges from app.include_router(router)."""
        edges: list[SyntheticEdge] = []

        if self._get_call_name(node) != "include_router":
            return edges

        if node.args:
            router_name = self._get_name(node.args[0])
            if router_name:
                edges.append(SyntheticEdge(
                    source_id=f"{file_path}::app",
                    target_id=f"router:{router_name}",
                    kind="registers",
                    metadata={
                        "synthesized_by": self.name,
                        "framework": "fastapi",
                    },
                ))

        # Extract prefix/tags kwargs
        for kw in node.keywords:
            if kw.arg == "prefix" and isinstance(kw.value, ast.Constant):
                pass  # metadata

        return edges

    def resolve(
        self, ref_name: str, candidates: list[dict[str, Any]],
    ) -> dict[str, Any] | None:
        """Resolve FastAPI naming conventions."""
        return None  # FastAPI uses explicit imports

    # ── AST Helpers ─────────────────────────────────────────────────

    @staticmethod
    def _get_call_name(call: ast.Call) -> str | None:
        if isinstance(call.func, ast.Name):
            return call.func.id
        if isinstance(call.func, ast.Attribute):
            return call.func.attr
        return None

    @staticmethod
    def _get_decorator_attr(decorator: ast.Call) -> str | None:
        """Get the attribute name from @app.get or @router.post."""
        if isinstance(decorator.func, ast.Attribute):
            return decorator.func.attr
        if isinstance(decorator.func, ast.Name):
            return decorator.func.id
        return None

    @staticmethod
    def _get_name(node: ast.expr) -> str | None:
        if isinstance(node, ast.Name):
            return node.id
        if isinstance(node, ast.Attribute):
            base = FastAPIResolver._get_name(node.value)
            return f"{base}.{node.attr}" if base else node.attr
        if isinstance(node, ast.Call):
            return FastAPIResolver._get_name(node.func)
        return None

    @staticmethod
    def _get_string_value(node: ast.expr) -> str | None:
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            return node.value
        return None

    @staticmethod
    def _get_list_value(node: ast.expr) -> list[str] | None:
        if isinstance(node, ast.List):
            return [
                e.value
                for e in node.elts
                if isinstance(e, ast.Constant) and isinstance(e.value, str)
            ]
        return None

"""Flask Framework Resolver (§28.2)

Detects Flask projects by scanning for @app.route patterns, extracts
route registration → handler edges, Blueprint registration.
"""

from __future__ import annotations

import ast
from pathlib import Path
from typing import Any

from coderadar.excludes import iter_project_files as _iter_files

from .base import (
    FrameworkExtraction,
    FrameworkResolver,
    SyntheticEdge,
    SyntheticNode,
)


class FlaskResolver(FrameworkResolver):
    """Resolves Flask-specific constructs:

    - Route registration: @app.route('/path') → handler functions
    - Blueprint registration: app.register_blueprint(bp)
    - Method-based routing: @app.get(), @app.post(), etc.
    - Error handlers: @app.errorhandler(code)
    """

    ROUTE_DECORATORS = frozenset({
        "route", "get", "post", "put", "delete", "patch",
        "before_request", "after_request", "errorhandler",
    })

    @property
    def name(self) -> str:
        return "flask"

    def detect(self, project_root: Path) -> bool:
        # Check for flask import in any Python file
        for py_file in _iter_files(project_root, suffixes=(".py",)):
            if py_file.name.startswith("__"):
                continue
            try:
                content = py_file.read_text(encoding="utf-8")
                if "flask" in content.lower():
                    return True
            except (OSError, UnicodeDecodeError):
                pass
        return False

    def claims_reference(self, name: str) -> bool:
        parts = name.rsplit(".", 1)[-1]
        return any(
            kw in parts.lower()
            for kw in ("blueprint", "route", "flask", "current_app", "g")
        )

    def extract(self, file_path: str, source: str) -> FrameworkExtraction:
        result = FrameworkExtraction(file_path=file_path)

        try:
            tree = ast.parse(source)
        except SyntaxError:
            return result

        app_name = self._detect_app_name(tree)

        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                route_nodes = self._extract_route_decorators(
                    node, app_name, file_path)
                result.nodes.extend(route_nodes)
                if route_nodes:
                    for rn in route_nodes:
                        handler_id = f"{file_path}::{node.name}"
                        result.edges.append(SyntheticEdge(
                            source_id=rn.id,
                            target_id=handler_id,
                            kind="handles",
                            metadata={
                                "synthesized_by": self.name,
                                "framework": "flask",
                                "methods": rn.metadata.get("methods", ["GET"]),
                            },
                        ))

            # Blueprint registration
            if isinstance(node, ast.Call):
                bp_edges = self._extract_blueprint_register(
                    node, file_path)
                result.edges.extend(bp_edges)
                # Flask-RESTful: api.add_resource(Resource, '/path')
                rest_edges = self._extract_add_resource(node, file_path)
                result.edges.extend(rest_edges)

        return result

    def _detect_app_name(self, tree: ast.Module) -> str | None:
        """Find the Flask app variable name."""
        for node in ast.walk(tree):
            if (
                isinstance(node, ast.Assign)
                and isinstance(node.value, ast.Call)
                and self._get_call_name(node.value) == "Flask"
            ):
                    for target in node.targets:
                        if isinstance(target, ast.Name):
                            return target.id
        return "app"  # default

    def _extract_route_decorators(
        self,
        func_node: ast.FunctionDef,
        app_name: str | None,
        file_path: str,
    ) -> list[SyntheticNode]:
        """Extract route SyntheticNodes from @app.route() decorators."""
        nodes: list[SyntheticNode] = []

        for decorator in func_node.decorator_list:
            # Handle @app.route(...) and @app.get(...) etc.
            if isinstance(decorator, ast.Call):
                decorator_name = self._get_decorator_name(decorator)
                if decorator_name in self.ROUTE_DECORATORS:
                    node = self._parse_route_decorator(
                        decorator, decorator_name, func_node.name, file_path)
                    if node:
                        nodes.append(node)

                # Handle @bp.route(...) for Blueprints
                elif isinstance(decorator.func, ast.Attribute):
                    decorator_name = decorator.func.attr
                    if decorator_name in self.ROUTE_DECORATORS:
                        node = self._parse_route_decorator(
                            decorator, decorator_name, func_node.name, file_path)
                        if node:
                            nodes.append(node)

        return nodes

    def _parse_route_decorator(
        self,
        decorator: ast.Call,
        decorator_name: str,
        handler_name: str,
        file_path: str,
    ) -> SyntheticNode | None:
        """Parse a route decorator into a SyntheticNode."""
        if not decorator.args:
            return None

        route_pattern = self._get_string_value(decorator.args[0])
        if not route_pattern:
            return None

        metadata: dict[str, Any] = {
            "pattern": route_pattern,
            "handler": handler_name,
        }

        if decorator_name == "route" and len(decorator.args) >= 2:
            methods = self._get_list_value(decorator.args[1])
            if methods:
                metadata["methods"] = methods
        elif decorator_name in ("get", "post", "put", "delete", "patch"):
            metadata["methods"] = [decorator_name.upper()]

        # Extract endpoint name if specified
        for kw in decorator.keywords:
            if kw.arg == "endpoint":
                metadata["endpoint"] = self._get_string_value(kw.value)

        return SyntheticNode(
            id=f"flask:route:{route_pattern}",
            name=route_pattern,
            kind="route",
            file_path=file_path,
            metadata=metadata,
        )

    def _extract_add_resource(
        self, node: ast.Call, file_path: str,
    ) -> list[SyntheticEdge]:
        """Extract edges from Flask-RESTful api.add_resource().

        Pattern: api.add_resource(HelloWorld, '/', '/hello')
        """
        edges: list[SyntheticEdge] = []
        call_name = self._get_call_name(node)
        if call_name != "add_resource":
            return edges
        if len(node.args) < 2:
            return edges
        resource = self._get_name(node.args[0])
        # Paths can be passed as multiple positional args or a list
        paths: list[str] = []
        for arg in node.args[1:]:
            if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
                paths.append(arg.value)
            elif isinstance(arg, ast.List):
                for elt in arg.elts:
                    if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                        paths.append(elt.value)
        for path in paths:
            edges.append(SyntheticEdge(
                source_id=f"flask:route:{path}",
                target_id=f"{file_path}::{resource}" if resource else f"{file_path}::unknown",
                kind="handles",
                metadata={
                    "synthesized_by": self.name,
                    "framework": "flask",
                    "pattern": path,
                    "resource": resource,
                },
            ))
        return edges

    def _extract_blueprint_register(
        self, node: ast.Call, file_path: str,
    ) -> list[SyntheticEdge]:
        """Extract edges from app.register_blueprint(bp)."""
        edges: list[SyntheticEdge] = []

        if self._get_call_name(node) != "register_blueprint":
            return edges

        if node.args:
            blueprint_name = self._get_name(node.args[0])
            if blueprint_name:
                edges.append(SyntheticEdge(
                    source_id=f"{file_path}::app",
                    target_id=f"{file_path}::{blueprint_name}",
                    kind="registers",
                    metadata={
                        "synthesized_by": self.name,
                        "framework": "flask",
                    },
                ))

        return edges

    def resolve(
        self, ref_name: str, candidates: list[dict[str, Any]],
    ) -> dict[str, Any] | None:
        """Resolve Flask naming conventions."""
        return None  # Flask uses direct imports, not naming conventions

    # ── AST Helpers ─────────────────────────────────────────────────

    @staticmethod
    def _get_call_name(call: ast.Call) -> str | None:
        if isinstance(call.func, ast.Name):
            return call.func.id
        if isinstance(call.func, ast.Attribute):
            return call.func.attr
        return None

    @staticmethod
    def _get_decorator_name(decorator: ast.Call) -> str | None:
        """Get the function name from a decorator call."""
        if isinstance(decorator.func, ast.Name):
            return decorator.func.id
        if isinstance(decorator.func, ast.Attribute):
            return decorator.func.attr
        return None

    @staticmethod
    def _get_name(node: ast.expr) -> str | None:
        if isinstance(node, ast.Name):
            return node.id
        if isinstance(node, ast.Attribute):
            base = FlaskResolver._get_name(node.value)
            return f"{base}.{node.attr}" if base else node.attr
        if isinstance(node, ast.Call):
            return FlaskResolver._get_name(node.func)
        return None

    @staticmethod
    def _get_string_value(node: ast.expr) -> str | None:
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            return node.value
        return None

    @staticmethod
    def _get_list_value(node: ast.expr) -> list[str] | None:
        if isinstance(node, ast.List):
            return [
                e.value
                for e in node.elts
                if isinstance(e, ast.Constant) and isinstance(e.value, str)
            ]
        return None

"""CodeRadar v0.5.7 — NestJS Framework Resolver (F.14)

Handles NestJS decorator-based module/controller/service declarations
for TypeScript. Produces synthetic route nodes and dependency edges.

Patterns:
  @Module({ controllers: [UserController], providers: [UserService] })
  @Controller('users')
  @Get(':id'), @Post(), @Put(':id'), @Delete(':id'), @Patch(':id')
  @Injectable()
"""

from __future__ import annotations

import re
from pathlib import Path
from typing import Any

from coderadar.excludes import iter_project_files as _iter_files

from .base import FrameworkExtraction, FrameworkResolver, SyntheticEdge, SyntheticNode

# ── Regex patterns ──────────────────────────────────────────────────────────

# @Module({ controllers: [A, B], providers: [X, Y], imports: [Z] })
_MODULE_RE = re.compile(
    r'@Module\s*\(\s*\{\s*'
    r'(?:(?:controllers|providers|imports|exports)\s*:\s*\[([^\]]*)\]\s*,?\s*)+'
    r'\s*\}\s*\)',
    re.IGNORECASE,
)

# Extract individual class references from a bracket list: [UserController, AdminController]
_CLASS_REF_LIST_RE = re.compile(r'\[([^\]]*)\]')

# @Controller('users'), @Controller()
_CONTROLLER_RE = re.compile(
    r'@Controller\s*(?:\(\s*[\"\']([^\"\']*)[\"\']\s*\))?',
    re.IGNORECASE,
)

# @Get(':id'), @Post(), @Put(':id'), @Delete(':id'), @Patch(':id')
# Also: @Get(), @HttpCode(200), @Header('X')
_HTTP_METHOD_RE = re.compile(
    r'@(Get|Post|Put|Delete|Patch|Head|Options|All)'
    r'\s*\(\s*(?:[\"\']([^\"\']*)[\"\']\s*)?\)',
    re.IGNORECASE,
)

# @Injectable()
_INJECTABLE_RE = re.compile(r'@Injectable\s*\(\s*\)', re.IGNORECASE)

# Class name: export class UserService { or export class UserController {
_CLASS_RE = re.compile(
    r'(?:export\s+)?class\s+(\w+)',
    re.MULTILINE,
)

_METHOD_MAP: dict[str, str] = {
    'Get': 'GET', 'Post': 'POST', 'Put': 'PUT', 'Delete': 'DELETE',
    'Patch': 'PATCH', 'Head': 'HEAD', 'Options': 'OPTIONS', 'All': 'ALL',
}

_HANDLER_DIRS = ['controllers', 'services', 'providers', 'modules', 'guards', 'interceptors']


class NestJSResolver(FrameworkResolver):
    """NestJS @Module / @Controller / @Injectable resolver for TypeScript."""

    @property
    def name(self) -> str:
        return "nestjs"

    def detect(self, project_root: Path) -> bool:
        pkg = project_root / "package.json"
        if pkg.exists():
            try:
                import json
                data = json.loads(pkg.read_text(encoding="utf-8"))
                deps = {**data.get("dependencies", {}), **data.get("devDependencies", {})}
                if "@nestjs/core" in deps:
                    return True
            except (OSError, json.JSONDecodeError, UnicodeDecodeError):
                pass
        for path in list(_iter_files(project_root, suffixes=(".ts",)))[:200]:
            try:
                if '@Module' in path.read_text(encoding="utf-8"):
                    return True
            except (OSError, UnicodeDecodeError):
                pass
        return False

    def claims_reference(self, name: str) -> bool:
        parts = name.rsplit(".", 1)[-1]
        return parts.endswith(
            ("Controller", "Service", "Module", "Guard", "Interceptor", "Provider")
        )

    def extract(self, file_path: str, source: str) -> FrameworkExtraction:
        nodes: list[SyntheticNode] = []
        edges: list[SyntheticEdge] = []

        if not file_path.endswith('.ts'):
            return FrameworkExtraction(file_path=file_path)

        # ── Find class name ──
        class_match = _CLASS_RE.search(source)
        class_name = class_match.group(1) if class_match else None

        # ── Controller route prefix ──
        controller_match = _CONTROLLER_RE.search(source)
        route_prefix = controller_match.group(1) if controller_match else ""

        # ── HTTP method routes ──
        for match in _HTTP_METHOD_RE.finditer(source):
            method_name = match.group(1)
            path_fragment = match.group(2) or ""
            method = _METHOD_MAP.get(method_name, 'GET')

            full_path = _join_paths(route_prefix, path_fragment.strip())
            effective_path = full_path or "/"

            line_no = source[:match.start()].count('\n') + 1

            nodes.append(SyntheticNode(
                id=f"nestjs:route:{file_path}:{line_no}:{method}:{effective_path}",
                name=f"{method} {effective_path}",
                kind="route",
                file_path=file_path,
                metadata={
                    "language": "typescript",
                    "framework": "nestjs",
                    "method": method,
                    "path": effective_path,
                    "line": line_no,
                    "annotation": f"@{method_name}",
                    "class": class_name,
                },
            ))

            # Find the method name right after the decorator
            handler_match = re.search(
                r'(?:async\s+)?(\w+)\s*\(', source[match.end():match.end() + 200]
            )
            if handler_match and class_name:
                handler_name = handler_match.group(1)
                edges.append(SyntheticEdge(
                    source_id=f"nestjs:route:{file_path}:{line_no}:{method}:{effective_path}",
                    target_id=f"{class_name}.{handler_name}",
                    kind="handles",
                    metadata={
                        "synthesizedBy": "nestjs-resolver",
                        "line": line_no,
                        "method": method,
                    },
                ))

        # ── @Module declarations: extract controller/provider/import edges ──
        for module_match in _MODULE_RE.finditer(source):
            module_text = module_match.group(0)
            line_no = source[:module_match.start()].count('\n') + 1

            # Extract class references from each array
            for array_match in re.finditer(r'(controllers|providers|imports|exports)\s*:\s*\[([^\]]*)\]', module_text):
                rel_kind = array_match.group(1)
                body = array_match.group(2)
                for ref in re.finditer(r'(\w+)', body):
                    ref_name = ref.group(1)
                    edges.append(SyntheticEdge(
                        source_id=f"{file_path}::{class_name or 'module'}",
                        target_id=ref_name,
                        kind=rel_kind.rstrip('s'),  # "controllers" → "controller"
                        metadata={
                            "synthesizedBy": "nestjs-resolver",
                            "line": line_no,
                            "reference": ref_name,
                        },
                    ))

        return FrameworkExtraction(file_path=file_path, nodes=nodes, edges=edges)

    def resolve(
        self, ref_name: str, candidates: list[dict[str, Any]],
    ) -> dict[str, Any] | None:
        if not candidates:
            return None
        for result in candidates:
            fp = result.get("file_path", "")
            for d in _HANDLER_DIRS:
                if f"/{d}/" in fp or f"\\{d}\\" in fp:
                    result["confidence"] = 0.85
                    return result
        result = candidates[0]
        result["confidence"] = 0.65
        return result


def _join_paths(base: str, fragment: str) -> str:
    if not base:
        return fragment
    if not fragment:
        return base
    if fragment.startswith('/') and base.endswith('/'):
        return base + fragment[1:]
    if not fragment.startswith('/') and not base.endswith('/'):
        return base + '/' + fragment
    return base + fragment

"""CodeRadar v0.5 — Spring Boot Framework Resolver (F.10 Phase 1)

Handles Spring Boot @RestController route annotations for Java.
Produces synthetic route nodes and handler edges.

Spring Boot patterns:
  @GetMapping("/users")                 → GET /users
  @GetMapping                           → inherits class base path
  @PostMapping(value = "/users")        → POST /users
  @RequestMapping(path="/api", method=GET) → GET /api
  @RequestMapping("/api") on class (no method=) → class base prefix
"""

from __future__ import annotations

import re
from pathlib import Path
from typing import Any

from coderadar.excludes import iter_project_files as _iter_files

from .base import FrameworkExtraction, FrameworkResolver, SyntheticEdge, SyntheticNode

# ── Regex patterns ──────────────────────────────────────────────────────────

# HTTP mapping annotation with optional path in parens:
#   @GetMapping
#   @GetMapping()
#   @GetMapping("/path")
#   @GetMapping(value="/path")
# Capture groups: (1) annotation name, (2) path (empty string if bare/empty parens)
_HTTP_ANNOTATION_RE = re.compile(
    r'@(GetMapping|PostMapping|PutMapping|DeleteMapping|PatchMapping|HeadMapping|OptionsMapping)'
    r'(?:\(\s*(?:value\s*=\s*)?["\']([^"\']*)["\']\s*\)'
    r'|\(\s*\))'
    r'|@(GetMapping|PostMapping|PutMapping|DeleteMapping|PatchMapping|HeadMapping|OptionsMapping)'
    r'(?!\s*\()',
    re.IGNORECASE,
)

# @RequestMapping on a method WITH method= parameter.
_REQUEST_MAPPING_RE = re.compile(
    r"@RequestMapping\s*\(\s*"
    r"(?:path\s*=\s*)?[\"']([^\"']*)[\"']"
    r"[^)]*\bmethod\s*=\s*(?:RequestMethod\.)?(\w+)"
    r"[^)]*\)",
    re.IGNORECASE | re.DOTALL,
)

# Class declaration: public class FooController {
_CLASS_DECL_RE = re.compile(
    r'@RestController\s*\n'
    r'(?:\s*@RequestMapping\s*\(\s*(?:value\s*=\s*)?["\']([^"\']+)["\']\s*\)\s*\n)?'
    r'(?:public|private|protected)\s+class\s+(\w+)',
    re.MULTILINE,
)

_METHOD_DECL_RE = re.compile(
    r'(?:public|private|protected)\s+(?:\w+(?:<[^>]*>)?\s+)?(\w+)\s*\(',
    re.MULTILINE,
)

_METHOD_MAP: dict[str, str] = {
    'GetMapping': 'GET', 'PostMapping': 'POST', 'PutMapping': 'PUT',
    'DeleteMapping': 'DELETE', 'PatchMapping': 'PATCH',
    'HeadMapping': 'HEAD', 'OptionsMapping': 'OPTIONS',
    'GET': 'GET', 'POST': 'POST', 'PUT': 'PUT', 'DELETE': 'DELETE',
    'PATCH': 'PATCH', 'HEAD': 'HEAD', 'OPTIONS': 'OPTIONS',
}

_HANDLER_DIRS = ['controller', 'controllers', 'api', 'handler', 'resource', 'endpoint']
_SERVICE_DIRS = ['service', 'services', 'repository', 'component', 'manager', 'facade']


class SpringBootResolver(FrameworkResolver):
    """Spring Boot @RestController / @RequestMapping resolver for Java."""

    @property
    def name(self) -> str:
        return "springboot"

    def detect(self, project_root: Path) -> bool:
        for marker in ('pom.xml', 'build.gradle', 'build.gradle.kts'):
            p = project_root / marker
            if p.exists():
                try:
                    if 'spring' in p.read_text(encoding="utf-8").lower():
                        return True
                except (OSError, UnicodeDecodeError):
                    pass
        for path in list(_iter_files(project_root, suffixes=(".java",)))[:200]:
            try:
                content = path.read_text(encoding="utf-8")
                if '@SpringBootApplication' in content or '@RestController' in content:
                    return True
            except (OSError, UnicodeDecodeError):
                pass
        return False

    def claims_reference(self, name: str) -> bool:
        parts = name.rsplit(".", 1)[-1]
        return parts.endswith(
            (
                "Controller",
                "Service",
                "Repository",
                "Component",
                "Handler",
                "Resource",
                "Facade",
            )
        ) or "ServiceImpl" in parts

    def extract(self, file_path: str, source: str) -> FrameworkExtraction:
        nodes: list[SyntheticNode] = []
        edges: list[SyntheticEdge] = []

        if not file_path.endswith('.java'):
            return FrameworkExtraction(file_path=file_path)

        # ── Find all per-class regions and their base paths ──
        # Build a list of (class_name, base_path, start_pos, end_pos)
        class_regions = list(_find_class_regions(source))

        # ── Pattern 1: @GetMapping-style annotations ──
        for match in _HTTP_ANNOTATION_RE.finditer(source):
            ann_name = match.group(1) or match.group(3)
            if not ann_name:
                continue
            path_fragment = match.group(2) or ""
            method = _METHOD_MAP.get(ann_name, 'GET')

            match_pos = match.start()
            class_name, base_path = _class_context(match_pos, class_regions)
            full_path = self._join_paths(base_path, path_fragment) if path_fragment else base_path

            handler_name = _find_handler_method(source, match.end())
            line_no = source[:match_pos].count('\n') + 1
            route_id = f"spring:route:{file_path}:{line_no}:{method}:{full_path}"

            nodes.append(SyntheticNode(
                id=route_id, name=f"{method} {full_path}", kind="route",
                file_path=file_path,
                metadata={
                    "language": "java", "framework": "spring-boot",
                    "method": method, "path": full_path,
                    "line": line_no, "annotation": ann_name, "class": class_name,
                },
            ))
            if handler_name:
                qualified = f"{class_name}.{handler_name}" if class_name else handler_name
                edges.append(SyntheticEdge(
                    source_id=route_id, target_id=qualified, kind="handles",
                    metadata={"synthesizedBy": "springboot-resolver", "line": line_no, "method": method},
                ))

        # ── Pattern 2: @RequestMapping with explicit method= ──
        for match in _REQUEST_MAPPING_RE.finditer(source):
            path_fragment = match.group(1)
            method_str = match.group(2)
            method = _METHOD_MAP.get(method_str.upper(), 'ANY') if method_str else 'ANY'

            match_pos = match.start()
            class_name, base_path = _class_context(match_pos, class_regions)
            full_path = self._join_paths(base_path, path_fragment)

            handler_name = _find_handler_method(source, match.end())
            line_no = source[:match_pos].count('\n') + 1
            route_id = f"spring:route:{file_path}:{line_no}:{method}:{full_path}"

            nodes.append(SyntheticNode(
                id=route_id, name=f"{method} {full_path}", kind="route",
                file_path=file_path,
                metadata={
                    "language": "java", "framework": "spring-boot",
                    "method": method, "path": full_path,
                    "line": line_no, "annotation": "RequestMapping", "class": class_name,
                },
            ))
            if handler_name:
                qualified = f"{class_name}.{handler_name}" if class_name else handler_name
                edges.append(SyntheticEdge(
                    source_id=route_id, target_id=qualified, kind="handles",
                    metadata={"synthesizedBy": "springboot-resolver", "line": line_no, "method": method},
                ))

        return FrameworkExtraction(file_path=file_path, nodes=nodes, edges=edges)

    def resolve(self, ref_name: str, candidates: list[dict[str, Any]]) -> dict[str, Any] | None:
        if not candidates:
            return None
        pref_dirs = _HANDLER_DIRS + _SERVICE_DIRS
        for result in candidates:
            fp = result.get("file_path", "")
            for d in pref_dirs:
                if f"/{d}/" in fp or f"\\{d}\\" in fp:
                    result["confidence"] = 0.85
                    return result
        result = candidates[0]
        result["confidence"] = 0.65
        return result

    @staticmethod
    def _join_paths(base: str, fragment: str) -> str:
        if not base:
            return fragment
        if not fragment:
            return base
        if fragment.startswith('/') and base.endswith('/'):
            return base + fragment[1:]
        if not fragment.startswith('/') and not base.endswith('/'):
            return base + '/' + fragment
        return base + fragment


# ── Helpers ─────────────────────────────────────────────────────────────────


def _find_class_regions(source: str) -> list[tuple[str | None, str, int, int]]:
    """Find all @RestController classes and their @RequestMapping base paths.

    Returns: list of (class_name, base_path, start_pos, end_pos)
    """
    regions: list[tuple[str | None, str, int, int]] = []

    for m in _CLASS_DECL_RE.finditer(source):
        base_path = m.group(1) or ""
        class_name = m.group(2)
        start = m.start()
        # Find end of this class (next class declaration or end of file)
        end = len(source)

        # Mark region end where previous region ended
        if regions:
            prev = regions[-1]
            regions[-1] = (prev[0], prev[1], prev[2], start)

        regions.append((class_name, base_path, start, end))

    return regions


def _class_context(pos: int, regions: list[tuple[str | None, str, int, int]]) -> tuple[str | None, str]:
    """Find the class context for a given position in source."""
    for name, base, start, end in reversed(regions):
        if start <= pos < end:
            return name, base
    return None, ""


def _find_handler_method(source: str, after_pos: int) -> str | None:
    window = source[after_pos:after_pos + 500]
    m = _METHOD_DECL_RE.search(window)
    return m.group(1) if m else None

"""Agent skill packs bundled with CodeRadar.

The `SKILL.md` files under this package are the single source of truth. They
live inside `python-source` so maturin copies them into the wheel: the drift
tests read them through `importlib.resources`, and an installed release reads
the same files `coderadar skills install` copies to disk.

Bundling is transport, not activation — agent harnesses discover skills as
directories on disk (`~/.claude/skills/<name>/SKILL.md`,
`~/.config/opencode/skills/<name>/SKILL.md`, project-local equivalents), not
inside site-packages. That is what `install()` is for.
"""

from __future__ import annotations

import re
from collections.abc import Iterable, Iterator
from dataclasses import dataclass
from importlib.resources import files
from pathlib import Path

#: Every skill shipped in the wheel, sorted for stable CLI output.
SKILL_NAMES = ("coderadar-cli", "coderadar-mcp")

_FRONTMATTER = re.compile(r"\A---\r?\n(.*?)\r?\n---[ \t]*(?:\r?\n|\Z)", re.DOTALL)
_FIELD = re.compile(r"^([A-Za-z_][\w-]*):[ \t]*(.*)$")


class SkillNotFound(KeyError):
    """Raised when a name does not identify a bundled skill."""


@dataclass(frozen=True)
class InstallResult:
    """One skill copy attempt."""

    path: Path
    status: str  # "installed", "updated" or "skipped"


def skill_names() -> tuple[str, ...]:
    """Names of the skill packs this distribution ships."""
    return SKILL_NAMES


def _root():
    return files(__name__)


def _selected(names: Iterable[str] | None) -> tuple[str, ...]:
    if not names:
        return SKILL_NAMES
    chosen: list[str] = []
    for name in names:
        if name not in SKILL_NAMES:
            raise SkillNotFound(
                f"unknown skill {name!r}; available: {', '.join(SKILL_NAMES)}"
            )
        if name not in chosen:
            chosen.append(name)
    return tuple(chosen)


def skill_text(name: str) -> str:
    """Return a bundled `SKILL.md` verbatim."""
    if name not in SKILL_NAMES:
        raise SkillNotFound(
            f"unknown skill {name!r}; available: {', '.join(SKILL_NAMES)}"
        )
    return (_root() / name / "SKILL.md").read_text(encoding="utf-8")


def _fields(text: str) -> dict[str, str]:
    match = _FRONTMATTER.match(text)
    if not match:
        return {}
    fields: dict[str, str] = {}
    for line in match.group(1).splitlines():
        if not line or line[0].isspace():
            continue
        field = _FIELD.match(line)
        if not field:
            continue
        value = field.group(2).strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
            value = value[1:-1]
        fields[field.group(1)] = value
    return fields


def skill_description(name: str) -> str:
    """Frontmatter trigger description for one skill.

    The description is what a harness reads before loading the full file, so
    a missing one is a packaging bug rather than an empty string.
    """
    fields = _fields(skill_text(name))
    description = fields.get("description", "").strip()
    if not description:
        raise ValueError(f"{name}/SKILL.md has no frontmatter description")
    declared = fields.get("name")
    if declared is not None and declared != name:
        raise ValueError(f"{name}/SKILL.md frontmatter name does not match its directory")
    return description


def iter_skills() -> Iterator[tuple[str, str]]:
    """Yield `(name, description)` for every bundled skill."""
    for name in SKILL_NAMES:
        yield name, skill_description(name)


def default_destinations(*, project: bool = False) -> tuple[Path, ...]:
    """Harness skill directories used when the caller names none.

    Personal installs go to Claude Code and OpenCode discovery paths on every
    OS; `project=True` targets the same harnesses inside the current
    directory. Anything else (Cursor, pi, a custom harness) takes `--dest`.
    """
    if project:
        root = Path.cwd()
        return (root / ".claude" / "skills", root / ".opencode" / "skills")
    home = Path.home()
    return (home / ".claude" / "skills", home / ".config" / "opencode" / "skills")


def _copy_tree(source, destination: Path) -> None:
    destination.mkdir(parents=True, exist_ok=True)
    for entry in source.iterdir():
        target = destination / entry.name
        if entry.is_dir():
            _copy_tree(entry, target)
        else:
            target.write_bytes(entry.read_bytes())


def install(
    destination: str | Path,
    *,
    names: Iterable[str] | None = None,
    force: bool = False,
) -> list[InstallResult]:
    """Copy bundled skills into `destination`.

    Existing skill directories are left alone unless `force` is set, so a
    re-run never clobbers local edits by accident.
    """
    dest = Path(destination).expanduser()
    results: list[InstallResult] = []
    for name in _selected(names):
        target = dest / name
        marker = target / "SKILL.md"
        existed = marker.is_file()
        if existed and not force:
            results.append(InstallResult(target, "skipped"))
            continue
        _copy_tree(_root() / name, target)
        results.append(InstallResult(target, "updated" if existed else "installed"))
    return results


__all__ = [
    "SKILL_NAMES",
    "InstallResult",
    "SkillNotFound",
    "default_destinations",
    "install",
    "iter_skills",
    "skill_description",
    "skill_names",
    "skill_text",
]

"""CodeRadar v3.6 — Visualizers: Graphviz DOT Output

Module dependency graph with cycle highlighting (Kosaraju SCC),
class hierarchy with inheritance edges, wired to real CodeGraph data.
"""

from __future__ import annotations

from typing import Any

from . import NothingToVisualize


def generate_dot(viz_type: str, args: list,
                 graph: Any | None = None) -> str:
    """Generate Graphviz DOT source for a visualization type.

    Args:
        viz_type: "dependencies", "hierarchy", or "call-graph"
        args: Additional arguments (ignored when graph is provided)
        graph: Optional CodeGraph instance for real data

    Types:
    - dependencies: Module dependency graph with SCC cycle clusters
    - hierarchy: Class inheritance styled as DOT
    - call-graph: Fan-out/fan-in around one function
    """
    if viz_type == "dependencies":
        return _dot_dependency_graph(args, graph)
    elif viz_type == "hierarchy":
        return _dot_class_hierarchy(args, graph)
    elif viz_type == "call-graph":
        return _dot_call_graph(args, graph)
    raise NothingToVisualize(f"Unknown visualization type: {viz_type}")


# ── Helpers ──────────────────────────────────────────────────────────────

def _safe_id(name: str) -> str:
    """A DOT-safe node id.

    Backslashes are escape characters in DOT, so an unescaped Windows path
    in an entity id produced a file that Graphviz could not parse.
    """
    out = []
    for ch in name:
        out.append(ch if (ch.isalnum() or ch == "_") else "_")
    return "n_" + "".join(out)


def _short_name(qualified: str) -> str:
    """A readable label for an entity id.

    Module ids all end `::module`, so taking the last segment labelled every
    module node "module". Fall back to the file stem in that case.
    """
    if "::" not in qualified:
        return qualified.split(".")[-1]
    head, _, tail = qualified.rpartition("::")
    if tail == "module":
        stem = head.replace(chr(92), "/").rsplit("/", 1)[-1]
        return stem.rsplit(".", 1)[0] or stem
    return tail


def _entities_of_kind(kind: str, limit: int = 500) -> list[dict[str, Any]]:
    """Every indexed entity of one kind.

    Both callers used to ask `graph.search_entities(...)` — a method
    `CodeGraph` does not have — and swallow the AttributeError, so they
    always returned an empty list and every DOT diagram fell through to the
    demo data. An empty query with a kind filter is the enumeration the core
    actually offers.
    """
    from coderadar._core import search_entities
    return list(search_entities("", limit, kind))


def _iter_modules(graph) -> list[dict[str, Any]]:
    """Yield all module entities from the graph."""
    return _entities_of_kind("module")


def _iter_classes(graph) -> list[dict[str, Any]]:
    """Yield all class entities from the graph."""
    return _entities_of_kind("class")


# ── Module Dependency Graph ──────────────────────────────────────────────

def _dot_dependency_graph(args: list, graph: Any | None = None) -> str:
    """Module dependency graph with cycle highlighting via Kosaraju SCC.

    Edges are extracted from module imports. An empty graph is an error,
    not an occasion for demo data.
    """
    lines = [
        "digraph Dependencies {",
        '    rankdir=LR;',
        '    node [shape=box, style=rounded, fontname="Helvetica"];',
        '    label="Module Dependencies";',
    ]

    if graph:
        edges = _extract_module_edges(graph)
        modules = set()
        for src, dst in edges:
            modules.add(src)
            modules.add(dst)
    else:
        raise NothingToVisualize(
            "No graph was provided to the dependency renderer.")

    if not edges:
        raise NothingToVisualize(
            "No module dependencies in the index. Run `coderadar init` or "
            "`coderadar reindex` in the project first."
        )

    # Find SCCs and highlight cycles
    sccs = _find_sccs(edges)
    cluster_idx = 0
    nodes_in_cycles: set[str] = set()

    for scc in sccs:
        if len(scc) > 1:
            cluster_idx += 1
            nodes_in_cycles.update(scc)
            lines.append(f"    subgraph cluster_{cluster_idx} {{")
            lines.append('        label="SCC (cycle)";')
            lines.append('        style=filled;')
            lines.append('        color=lightcoral;')
            lines.append('        fontcolor=darkred;')
            for node in sorted(scc):
                lines.append(f"        {_safe_id(node)};")
            lines.append("    }")

    # Emit standalone nodes with tooltips
    for module in sorted(modules):
        safe = _safe_id(module)
        label = _short_name(module)
        if module not in nodes_in_cycles:
            lines.append(f'    {safe} [label="{label}", tooltip="{module}"];')

    # Emit edges
    for src, dst in edges:
        lines.append(f"    {_safe_id(src)} -> {_safe_id(dst)};")

    lines.append("}")
    return "\n".join(lines)


def _extract_module_edges(graph) -> list[tuple[str, str]]:
    """Resolved module→module import edges.

    The `imports` list on a module entity holds import-statement *entity
    ids* (`...::import@3`), whose only payload is the raw source line — so
    using them as edge targets drew one node per import statement and no
    dependency at all. The resolved edges live in the core's importer
    index, which a depth-1 `imports` traversal reads.
    """
    from coderadar._core import traverse as _traverse

    edges: list[tuple[str, str]] = []
    module_ids = {m.get("id", "") for m in _iter_modules(graph)}

    for mod_id in sorted(module_ids):
        if not mod_id:
            continue
        for row in _traverse(mod_id, 1, ["imports"], "out", None):
            target = row.get("id", "")
            if target and target != mod_id and target in module_ids:
                edges.append((mod_id, target))
    return edges


# ── Class Hierarchy ──────────────────────────────────────────────────────

def _dot_class_hierarchy(args: list, graph: Any | None = None) -> str:
    """Class hierarchy as Graphviz DOT with real inheritance edges.

    When a CodeGraph is provided, walks class entities and their
    parent classes to build the inheritance DAG.
    """
    lines = [
        "digraph Hierarchy {",
        '    rankdir=BT;',
        '    node [shape=record, fontname="Helvetica", style=rounded];',
        '    edge [arrowhead=empty];',
    ]

    if graph:
        classes = _iter_classes(graph)

        # Emit class nodes
        for cls in classes:
            cls_id = cls.get("id", "")
            name = cls.get("name", _short_name(cls_id))
            methods = cls.get("methods") or cls.get("function_ids") or []
            method_str = "|".join(
                [f"+ {m if isinstance(m, str) else m.get('name', '?')}()"
                 for m in methods[:6]]
            )
            label = f"{{{name}|{method_str}}}" if method_str else f"{{{name}}}"
            lines.append(f'    {_safe_id(cls_id)} [label="{label}"];')

        # Emit inheritance edges (parent → child, reversed for rankdir=BT).
        # The class dict exposes resolved base *names* under `bases`; the
        # keys this read before (`parent_class`, `parent`) are not on it, so
        # no hierarchy edge was ever drawn.
        by_name = {c.get("name", ""): c.get("id", "") for c in classes}
        for cls in classes:
            cls_id = cls.get("id", "")
            for base in cls.get("bases") or []:
                base_id = by_name.get(base)
                if base_id and base_id != cls_id:
                    lines.append(
                        f"    {_safe_id(base_id)} -> {_safe_id(cls_id)};"
                    )
    else:
        raise NothingToVisualize(
            "No graph was provided to the hierarchy renderer.")

    if len(lines) == 4:
        raise NothingToVisualize(
            "No classes in the index. Run `coderadar init` or "
            "`coderadar reindex` in the project first."
        )

    lines.append("}")
    return "\n".join(lines)


# ── Kosaraju SCC ─────────────────────────────────────────────────────────

def _find_sccs(edges: list[tuple[str, str]]) -> list[set[str]]:
    """Find strongly-connected components using Kosaraju's algorithm."""
    # Build adjacency list
    adj: dict[str, set[str]] = {}
    for src, dst in edges:
        adj.setdefault(src, set()).add(dst)
        adj.setdefault(dst, set())

    # First pass: compute finish order
    visited: set[str] = set()
    order: list[str] = []

    def dfs1(node: str) -> None:
        stack = [(node, False)]
        while stack:
            n, done = stack.pop()
            if done:
                order.append(n)
                continue
            if n in visited:
                continue
            visited.add(n)
            stack.append((n, True))
            for neighbor in sorted(adj.get(n, set()), reverse=True):
                if neighbor not in visited:
                    stack.append((neighbor, False))

    for node in sorted(adj):
        if node not in visited:
            dfs1(node)

    # Reverse graph
    rev_adj: dict[str, set[str]] = {}
    for src, dst in edges:
        rev_adj.setdefault(dst, set()).add(src)
        rev_adj.setdefault(src, set())

    visited.clear()
    components: list[set[str]] = []

    def dfs2(start: str) -> set[str]:
        comp: set[str] = set()
        stack = [start]
        while stack:
            n = stack.pop()
            if n in visited:
                continue
            visited.add(n)
            comp.add(n)
            for neighbor in rev_adj.get(n, set()):
                if neighbor not in visited:
                    stack.append(neighbor)
        return comp

    for node in reversed(order):
        if node not in visited:
            components.append(dfs2(node))

    return components


# ── Call Graph ───────────────────────────────────────────────────────────

def _dot_call_graph(args: list, graph: Any | None = None) -> str:
    """Fan-out (or fan-in) around one function, as DOT.

    The Mermaid renderer in `call_graph.py` already walks the graph; this
    reuses that walk so the two formats cannot disagree about the edges,
    and only the rendering differs.
    """
    from .call_graph import _default_entry_point, _gather_fan_in, _gather_fan_out

    if graph is None:
        raise NothingToVisualize(
            "No graph was provided to the call-graph renderer.")

    # No arg: resolve a real `main` when the index has one, else the same
    # actionable error the Mermaid renderer raises (formats must agree).
    func_name = args[0] if args else _default_entry_point(graph)
    direction = args[1] if len(args) > 1 else "out"
    max_depth = int(args[2]) if len(args) > 2 else 5

    if not func_name:
        raise NothingToVisualize(
            "call-graph needs a function to start from, e.g. "
            "`coderadar visualize call-graph src/app.py::main`."
        )

    entity_id = func_name
    if "::" not in func_name:
        from coderadar._core import search_entities
        hits = search_entities(func_name, 1)
        if hits:
            entity_id = hits[0].get("id", func_name)

    visited: set[str] = set()
    edges: list[tuple[str, str, float]] = []
    if direction == "out":
        _gather_fan_out(graph, entity_id, max_depth, 0.0, visited, edges)
    else:
        _gather_fan_in(graph, entity_id, max_depth, 0.0, visited, edges)

    if not edges:
        raise NothingToVisualize(
            f"No call edges found {'from' if direction == 'out' else 'to'} "
            f"`{func_name}`. Either the index is empty (run `coderadar "
            f"init` or `coderadar reindex` in the project first) or that "
            f"function neither calls nor is called by anything indexed."
        )

    lines = [
        "digraph CallGraph {",
        '    rankdir=LR;',
        '    node [shape=box, fontname="Helvetica", style=rounded];',
    ]
    for node in sorted({e for src, dst, _ in edges for e in (src, dst)}):
        lines.append(f'    {_safe_id(node)} [label="{_short_name(node)}"];')
    for src, dst, _ in edges:
        lines.append(f"    {_safe_id(src)} -> {_safe_id(dst)};")
    lines.append("}")
    return "\n".join(lines)

"""CodeRadar v3.6 — Visualizers: Mermaid / Graphviz (§18)

Class hierarchy, module dependencies, and call graph visualization
with real data from the CodeGraph projection.
"""

from __future__ import annotations

from typing import Any

from . import NothingToVisualize


def generate_mermaid(viz_type: str, args: list[str],
                     graph: Any | None = None) -> str:
    """Generate Mermaid diagram source for a visualization type.

    Args:
        viz_type: "hierarchy", "call-graph", or "dependencies"
        args: Positional arguments (e.g., entity IDs, filters)
        graph: Optional CodeGraph instance for real data

    Types:
    - hierarchy: Class inheritance DAG
    - call-graph: Function call graph (by entity ID or name)
    - dependencies: Module dependency graph
    """
    if viz_type == "hierarchy":
        return _mermaid_class_hierarchy(args, graph)
    elif viz_type == "call-graph":
        return _mermaid_call_graph(args, graph)
    elif viz_type == "dependencies":
        return _mermaid_dependency_graph(args, graph)
    raise NothingToVisualize(f"Unknown visualization type: {viz_type}")


def _safe_id(name: str) -> str:
    """A Mermaid-safe node id.

    Entity ids carry path separators — backslashes on Windows — which the
    chained `.replace` calls this used to do left untouched.
    """
    return "n_" + "".join(
        ch if (ch.isalnum() or ch == "_") else "_" for ch in name
    )


def _truncated_label(qualified: str, max_len: int = 40) -> str:
    """Create a short display label from a qualified name."""
    name = qualified.split("::")[-1] if "::" in qualified else qualified
    if len(name) > max_len:
        return name[:max_len-3] + "..."
    return name


# ── Class Hierarchy ──────────────────────────────────────────────────────

def _mermaid_class_hierarchy(args: list[str],
                              graph: Any | None = None) -> str:
    """Render a class inheritance hierarchy as Mermaid classDiagram."""
    lines = ["classDiagram"]

    if graph:
        try:
            # Walk all classes and their subclasses
            visited = set()

            classes = list(_iter_classes(graph))
            by_name = {c.get("name", ""): cid for cid, c in classes}
            for cls_id, cls_data in classes:
                safe = _safe_id(cls_id)
                label = _truncated_label(cls_data.get("name", cls_id))
                lines.append(f"    class {safe} {{")
                lines.append(f"        +{label}")
                lines.append("    }")
                visited.add(cls_id)

            # Inheritance comes from the resolved `bases` names; callees_of
            # returns call edges, which are not inheritance.
            for cls_id, cls_data in classes:
                for base in cls_data.get("bases") or []:
                    base_id = by_name.get(base)
                    if base_id and base_id != cls_id:
                        lines.append(
                            f"    {_safe_id(base_id)} <|-- {_safe_id(cls_id)}"
                        )

            if len(visited) > 0:
                return "\n".join(lines)
        except Exception as exc:
            raise NothingToVisualize(
                f"Could not read the class hierarchy: {exc}") from exc

    raise NothingToVisualize(
        "No classes in the index. Run `coderadar init` or "
        "`coderadar reindex` in the project first."
    )


# ── Call Graph ──────────────────────────────────────────────────────────

def _mermaid_call_graph(args: list[str],
                         graph: Any | None = None) -> str:
    """Render a function call graph as Mermaid flowchart.

    Uses real callers_of/callees_of data when graph is available.
    """
    lines = ["flowchart TD"]

    if graph and args:
        entity_id = args[0]
        depth_limit = int(args[1]) if len(args) > 1 else 3
        direction = args[2] if len(args) > 2 else "both"

        visited: set = set()
        edges: list[tuple] = []
        _gather_call_edges(graph, entity_id, depth_limit, direction, visited, edges)

        if edges:
            for src, dst, conf in edges:
                safe_src = _safe_id(src)
                safe_dst = _safe_id(dst)
                if conf < 0.8:
                    lines.append(f"    {safe_src} -.->|{conf:.0%}| {safe_dst}")
                else:
                    lines.append(f"    {safe_src} --> {safe_dst}")
            return "\n".join(lines)

    raise NothingToVisualize(
        "No call edges found for that entity. Either the index is empty "
        "(run `coderadar init` or `coderadar reindex` in the project "
        "first) or nothing indexed calls it and it calls nothing indexed."
    )


def _gather_call_edges(graph, entity_id: str, depth: int,
                        direction: str, visited: set,
                        edges: list) -> None:
    """Recursively gather call edges from the graph."""
    if depth <= 0 or entity_id in visited:
        return
    visited.add(entity_id)

    if direction in ("out", "both"):
        for callee in graph.callees(entity_id):
            edges.append((entity_id, callee.get("id", callee.get("name", "?")), 1.0))
            _gather_call_edges(graph, callee.get("id", ""), depth - 1,
                              direction, visited, edges)

    if direction in ("in", "both"):
        for caller in graph.callers(entity_id):
            edges.append((caller.get("id", caller.get("name", "?")), entity_id, 1.0))
            _gather_call_edges(graph, caller.get("id", ""), depth - 1,
                              direction, visited, edges)


# ── Dependency Graph ────────────────────────────────────────────────────

def _mermaid_dependency_graph(args: list[str],
                                graph: Any | None = None) -> str:
    """Render module dependencies as Mermaid flowchart.

    Shows import relationships between modules.
    """
    lines = ["flowchart LR"]

    if graph:
        try:
            # Same resolved module→module edges the DOT renderer draws:
            # `search_entities("module")` is a *text* search for the word
            # "module", so it enumerated nothing unless a module was
            # literally named that; and `callees_of(module)` follows CALLS,
            # not IMPORTS. The shared helper reads the importer index via a
            # depth-1 `imports` traversal instead.
            from .graphviz_viz import _entities_of_kind, _extract_module_edges
            modules = {m.get("id", ""): m.get("name", m.get("id", "?"))
                       for m in _entities_of_kind("module")}
            edges = _extract_module_edges(graph)
            seen: set[str] = set()
            for src, dst in edges:
                seen.add(src)
                seen.add(dst)
            for mod_id in sorted(seen):
                label = _truncated_label(modules.get(mod_id, mod_id))
                lines.append(f"    {_safe_id(mod_id)}[\"{label}\"]")
            for src, dst in edges:
                lines.append(
                    f"    {_safe_id(src)} --> {_safe_id(dst)}"
                )
            if seen:
                return "\n".join(lines)
        except NothingToVisualize:
            raise
        except Exception as exc:
            raise NothingToVisualize(f"Could not read the graph: {exc}") from exc

    raise NothingToVisualize(
        "No module dependencies in the index. Run `coderadar init` or "
        "`coderadar reindex` in the project first."
    )


def _iter_classes(graph):
    """Iterate over all class entities in the graph.

    This used to *text-search* for the word "class", which matches
    `from dataclasses import dataclass` and every docstring mentioning one,
    and misses any class whose name does not contain it. An empty query with
    a kind filter enumerates the real thing.
    """
    from coderadar._core import search_entities
    for cls in search_entities("", 500, "class"):
        yield cls.get("id", ""), cls

